fn library_media_kind(extension: &str) -> &'static str {
    match extension
        .trim_start_matches('.')
        .to_ascii_lowercase()
        .as_str()
    {
        "mp3" | "flac" | "ogg" | "opus" | "aac" | "m4a" | "wav" => "Audio",
        "mp4" | "mkv" | "avi" | "mov" | "webm" => "Video",
        "txt" | "pdf" | "epub" | "mobi" => "Book",
        _ => "File",
    }
}

async fn sha256_local_file(path: &Path) -> Option<String> {
    use tokio::io::AsyncReadExt as _;

    let mut file = tokio::fs::File::open(path).await.ok()?;
    let mut hasher = Sha256::new();
    let mut buffer = [0_u8; 32 * 1024];
    loop {
        let read = file.read(&mut buffer).await.ok()?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Some(hex::encode(hasher.finalize()))
}

fn is_sha256_hex(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

/// Resolve a player/library content identifier against the share index.
///
/// Native library projections expose a real sha256:<digest> identifier for
/// local files, while the Soulseek-facing share index historically addressed
/// the same files by virtual filename or its bounded compatibility hash. Keep
/// all three forms usable by the ticket and stream paths.
async fn find_shared_entry_for_content(
    state: &AppState,
    filename: Option<&str>,
    content_id: Option<&str>,
) -> Option<FileEntry> {
    let expected_sha256 = content_id
        .and_then(|value| value.strip_prefix("sha256:"))
        .filter(|value| is_sha256_hex(value));
    let (direct, candidates) = {
        let shares = state.shares.read().await;
        let direct = shares
            .entries
            .iter()
            .find(|entry| {
                filename.is_some_and(|value| entry.filename == value)
                    || content_id.is_some_and(|value| {
                        entry.filename == value
                            || stable_content_hash(&entry.filename, entry.size).to_string() == value
                    })
            })
            .cloned();
        let candidates = if expected_sha256.is_some() {
            shares
                .entries
                .iter()
                .filter_map(|entry| {
                    shares
                        .local_paths
                        .get(&entry.filename)
                        .map(|path| (entry.clone(), path.clone()))
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        (direct, candidates)
    };
    if direct.is_some() {
        return direct;
    }

    let expected_sha256 = expected_sha256?;
    for (entry, path) in candidates {
        if sha256_local_file(&path)
            .await
            .is_some_and(|actual| actual.eq_ignore_ascii_case(expected_sha256))
        {
            return Some(entry);
        }
    }
    None
}

fn normalize_library_browser_path(raw_path: Option<String>) -> Result<String, String> {
    let raw_path = raw_path.unwrap_or_default();
    if raw_path.len() > 4_096 {
        return Err("library browser path is too long".to_owned());
    }
    let normalized = raw_path.replace('\\', "/");
    let mut segments = Vec::new();
    for segment in normalized.split('/') {
        let segment = segment.trim();
        if segment.is_empty() {
            continue;
        }
        if segment == "."
            || segment == ".."
            || segment.chars().any(char::is_control)
        {
            return Err("library browser path contains an invalid segment".to_owned());
        }
        segments.push(segment);
    }
    Ok(segments.join("/"))
}

fn library_browser_relative_path(filename: &str, path: &str) -> Option<String> {
    let filename = filename.replace('\\', "/");
    if path.is_empty() {
        return Some(filename);
    }
    filename
        .strip_prefix(path)
        .and_then(|relative| relative.strip_prefix('/'))
        .map(ToOwned::to_owned)
}

fn library_browser_breadcrumbs(path: &str) -> Vec<serde_json::Value> {
    let mut breadcrumbs = vec![serde_json::json!({
        "name": "Library",
        "path": "",
    })];
    let mut prefix = String::new();
    for segment in path.split('/').filter(|segment| !segment.is_empty()) {
        if !prefix.is_empty() {
            prefix.push('/');
        }
        prefix.push_str(segment);
        breadcrumbs.push(serde_json::json!({
            "name": segment,
            "path": prefix,
        }));
    }
    breadcrumbs
}

fn library_browser_query_terms(raw_query: Option<String>) -> Vec<String> {
    raw_query
        .unwrap_or_default()
        .split_whitespace()
        .map(str::to_ascii_lowercase)
        .filter(|term| !term.is_empty())
        .collect()
}

fn library_browser_kind_filter(raw_kinds: Option<String>) -> Option<HashSet<String>> {
    let kinds = raw_kinds
        .unwrap_or_default()
        .split(',')
        .map(str::trim)
        .filter(|kind| !kind.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<HashSet<_>>();
    (!kinds.is_empty()).then_some(kinds)
}

fn library_browser_entry_matches(
    entry: &FileEntry,
    query_terms: &[String],
    kinds: Option<&HashSet<String>>,
) -> bool {
    let kind_matches = kinds.is_none_or(|kinds| {
        kinds.contains(&library_media_kind(&entry.extension).to_ascii_lowercase())
    });
    let filename = entry.filename.replace('\\', "/");
    kind_matches
        && query_terms
            .iter()
            .all(|term| filename.to_ascii_lowercase().contains(term))
}

/// Return the real share-backed files behind the Web UI's local library
/// explorer. The old compatibility implementation returned metadata records
/// from LibraryStore, which have no streamable path and ignored path, query,
/// kinds, and directory navigation.
async fn library_browser_response(
    state: &AppState,
    raw_query: Option<&str>,
) -> HttpResponse {
    let path = match normalize_library_browser_path(query_parameter(raw_query, "path")) {
        Ok(path) => path,
        Err(error) => return routing::bad_request_response(&error),
    };
    let query_terms = library_browser_query_terms(query_parameter(raw_query, "query"));
    let kinds = library_browser_kind_filter(query_parameter(raw_query, "kinds"));
    let limit = query_parameter(raw_query, "limit")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(100)
        .clamp(1, 1_000);
    let offset = query_parameter(raw_query, "offset")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0);

    let (entries, local_paths, scan_failed) = {
        let shares = state.shares.read().await;
        (
            shares.entries.clone(),
            shares.local_paths.clone(),
            !shares.scan_errors.is_empty(),
        )
    };
    if scan_failed {
        return routing::service_unavailable_response("share browse unavailable");
    }

    let is_search = !query_terms.is_empty();
    let mut files = Vec::new();
    let mut directory_stats = BTreeMap::<String, (usize, HashSet<String>)>::new();
    for entry in entries.iter().filter(|entry| {
        library_browser_entry_matches(entry, &query_terms, kinds.as_ref())
    }) {
        if is_search {
            files.push(entry.clone());
            continue;
        }
        let Some(relative) = library_browser_relative_path(&entry.filename, &path) else {
            continue;
        };
        let segments = relative
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        if segments.len() == 1 {
            files.push(entry.clone());
        } else if segments.len() > 1 {
            let summary = directory_stats
                .entry(segments[0].to_owned())
                .or_insert_with(|| (0, HashSet::new()));
            summary.0 += 1;
            if segments.len() > 2 {
                summary.1.insert(segments[1].to_owned());
            }
        }
    }
    files.sort_by(|left, right| left.filename.cmp(&right.filename));

    let total_files = files.len();
    let directories = directory_stats
        .iter()
        .map(|(name, (file_count, children))| {
            let directory_path = if path.is_empty() {
                name.clone()
            } else {
                format!("{path}/{name}")
            };
            serde_json::json!({
                "name": name,
                "path": directory_path,
                "fileCount": file_count,
                "childDirectoryCount": children.len(),
            })
        })
        .collect::<Vec<_>>();
    let total_directories = directories.len();
    let page = files
        .iter()
        .skip(offset)
        .take(limit)
        .collect::<Vec<_>>();
    let mut file_values = Vec::with_capacity(page.len());
    for entry in page {
        let local_path = local_paths.get(&entry.filename);
        file_values.push(
            native_library_item_value(
                entry,
                local_path.map(PathBuf::as_path),
                &entry.filename,
            )
            .await,
        );
    }
    let returned_files = file_values.len();
    routing::ok_response(
        serde_json::json!({
            "path": path,
            "breadcrumbs": library_browser_breadcrumbs(&path),
            "directories": directories,
            "files": file_values,
            "totalFiles": total_files,
            "totalDirectories": total_directories,
            "offset": offset,
            "limit": limit,
            "hasMore": offset.saturating_add(returned_files) < total_files,
            "duplicatesRemoved": 0,
        })
        .to_string(),
    )
}

async fn native_library_item_value(
    entry: &FileEntry,
    local_path: Option<&Path>,
    display_path: &str,
) -> serde_json::Value {
    let sha256 = match local_path {
        Some(path) => sha256_local_file(path).await,
        None => None,
    };
    let content_id = sha256.as_ref().map_or_else(
        || stable_content_hash(&entry.filename, entry.size).to_string(),
        |sha256| format!("sha256:{sha256}"),
    );
    let file_name = display_path
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(display_path);
    serde_json::json!({
        "contentId": content_id,
        "path": display_path,
        "fileName": file_name,
        "bytes": entry.size,
        "mediaKind": library_media_kind(&entry.extension),
        "sha256": sha256,
        "duplicateCount": 1,
    })
}

fn library_entry_matches(
    entry: &FileEntry,
    query: Option<&str>,
    kinds: Option<&HashSet<String>>,
) -> bool {
    let query_matches = query.is_none_or(|query| {
        entry
            .filename
            .to_ascii_lowercase()
            .contains(&query.to_ascii_lowercase())
    });
    let kind_matches = kinds.is_none_or(|kinds| {
        kinds.contains(&library_media_kind(&entry.extension).to_ascii_lowercase())
    });
    query_matches && kind_matches
}

async fn native_library_items_search_json(state: &AppState, raw_query: Option<&str>) -> String {
    let query = query_parameter(raw_query, "query")
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty());
    let kinds = query_parameter(raw_query, "kinds")
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
        .map(|value| {
            value
                .split(',')
                .map(str::trim)
                .filter(|kind| !kind.is_empty())
                .map(str::to_ascii_lowercase)
                .collect::<HashSet<_>>()
        });
    let limit = query_parameter(raw_query, "limit")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(100)
        .clamp(1, 100);

    let (entries, local_paths) = {
        let shares = state.shares.read().await;
        (shares.entries.clone(), shares.local_paths.clone())
    };
    let mut candidates = entries
        .into_iter()
        .filter(|entry| library_entry_matches(entry, query.as_deref(), kinds.as_ref()))
        .take(limit)
        .map(|entry| {
            let local_path = local_paths.get(&entry.filename).cloned();
            let display_path = entry.filename.clone();
            (entry, local_path, display_path)
        })
        .collect::<Vec<_>>();

    if candidates.is_empty() {
        let mut settings = state.share_settings.read().await.clone();
        let downloads = state
            .downloads_dir
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        if downloads.is_dir()
            && !settings
                .directories
                .iter()
                .any(|directory| directory.local_path == downloads)
        {
            settings.directories.push(ShareDirectory {
                raw: downloads.display().to_string(),
                alias: "downloads".to_owned(),
                local_path: downloads,
                is_excluded: false,
            });
        }
        let case_sensitive = *state
            .controller_case_sensitive_regex
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let filters = compile_controller_regexes_for_request(
            settings.filters.clone(),
            case_sensitive,
            state.config.controller_profile,
        )
        .expect("validated share filters must compile");
        let scan = scan_share_dirs(
            &settings.directories,
            settings.follow_symlinks,
            settings.include_hidden,
            settings.max_files,
            settings.probe_media_attributes,
            settings.cache_workers,
            &filters,
        );
        candidates = scan
            .entries
            .into_iter()
            .filter(|entry| library_entry_matches(entry, query.as_deref(), kinds.as_ref()))
            .take(limit)
            .map(|entry| {
                let local_path = scan.local_paths.get(&entry.filename).cloned();
                let display_path = local_path
                    .as_deref()
                    .and_then(|path| {
                        settings
                            .directories
                            .iter()
                            .filter(|directory| !directory.is_excluded)
                            .find_map(|directory| {
                                path.strip_prefix(&directory.local_path)
                                    .ok()
                                    .map(virtual_share_path)
                            })
                    })
                    .unwrap_or_else(|| entry.filename.clone());
                (entry, local_path, display_path)
            })
            .collect();
    }

    let mut items = Vec::with_capacity(candidates.len());
    for (entry, local_path, display_path) in candidates {
        items.push(native_library_item_value(&entry, local_path.as_deref(), &display_path).await);
    }
    serde_json::json!({"items": items}).to_string()
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct LibraryStore {
    records: Vec<LibraryItemRecord>,
    next_id: u64,
    health_scans: Vec<LibraryHealthScanRecord>,
    next_health_scan_id: u64,
    updated_at: u64,
    remediation_jobs: Vec<LibraryRemediationJob>,
    next_remediation_job_id: u64,
}

impl LibraryStore {
    fn new() -> Self {
        Self {
            records: Vec::new(),
            next_id: 1,
            health_scans: Vec::new(),
            next_health_scan_id: 1,
            updated_at: unix_timestamp(),
            remediation_jobs: Vec::new(),
            next_remediation_job_id: 1,
        }
    }

    fn from_persisted(records: Vec<crate::persistence::LibraryItemRecord>) -> Self {
        let mut next_id = 1;
        let mut updated_at = unix_timestamp();
        for record in &records {
            if let Some(number) = record
                .id
                .strip_prefix("lib-")
                .and_then(|value| value.parse::<u64>().ok())
            {
                next_id = next_id.max(number.saturating_add(1));
            }
        }
        let mut seen_ids = std::collections::HashSet::new();
        let records = records
            .into_iter()
            .filter(|record| seen_ids.insert(record.id.clone()))
            .take(MAX_LIBRARY_ITEMS)
            .map(|record| {
                let created_at = u64::try_from(record.created_at).unwrap_or(0);
                updated_at = updated_at.max(created_at);
                LibraryItemRecord {
                    id: record.id,
                    artist: record.artist,
                    title: record.title,
                    kind: record.kind,
                    created_at,
                }
            })
            .collect();
        Self {
            records,
            next_id,
            health_scans: Vec::new(),
            next_health_scan_id: 1,
            updated_at,
            remediation_jobs: Vec::new(),
            next_remediation_job_id: 1,
        }
    }

    fn create_health_scan(&mut self, library_path: String) -> Option<LibraryHealthScanRecord> {
        let id = format!("scan-{}", self.allocate_health_scan_id());
        let record = LibraryHealthScanRecord {
            id,
            library_path,
            items: self.records.len(),
            issues: self.health_issues(),
            status: "completed".to_owned(),
            started_at: self.updated_at,
            updated_at: self.updated_at,
        };
        if self.health_scans.len() == MAX_LIBRARY_HEALTH_SCANS {
            self.health_scans.remove(0);
        }
        self.health_scans.push(record.clone());
        Some(record)
    }

    fn start_health_scan(
        &mut self,
        library_path: String,
    ) -> Result<LibraryHealthScanRecord, String> {
        self.refresh_health_scans();
        if let Some(active) = self
            .health_scans
            .iter()
            .find(|scan| scan.status == "running")
        {
            return Err(active.id.clone());
        }
        let id = format!("scan-{}", self.allocate_health_scan_id());
        let now = unix_timestamp();
        let record = LibraryHealthScanRecord {
            id,
            library_path,
            items: self.records.len(),
            issues: Vec::new(),
            status: "running".to_owned(),
            started_at: now,
            updated_at: now,
        };
        if self.health_scans.len() == MAX_LIBRARY_HEALTH_SCANS {
            self.health_scans.remove(0);
        }
        self.health_scans.push(record.clone());
        Ok(record)
    }

    fn refresh_health_scans(&mut self) {
        let now = unix_timestamp();
        let issues = self.health_issues();
        for scan in &mut self.health_scans {
            if scan.status == "running" && now.saturating_sub(scan.started_at) >= 1 {
                scan.status = "completed".to_owned();
                scan.issues = issues.clone();
                scan.updated_at = now;
            }
        }
    }

    fn health_scan(&self, id: &str) -> Option<LibraryHealthScanRecord> {
        self.health_scans.iter().find(|scan| scan.id == id).cloned()
    }

    fn remediation_job(&self, id: &str) -> Option<LibraryRemediationJob> {
        self.remediation_jobs
            .iter()
            .find(|job| job.id == id)
            .cloned()
    }

    fn remediate_selected(
        &mut self,
        issue_ids: &[String],
    ) -> Result<LibraryRemediationJob, String> {
        let issues = self.health_issues();
        let mut fixed = Vec::new();
        for issue_id in issue_ids {
            let Some(issue) = issues
                .iter()
                .find(|issue| issue["id"].as_str() == Some(issue_id.as_str()))
            else {
                continue;
            };
            if issue["type"].as_str() != Some("missing_kind") {
                continue;
            }
            let Some(item_id) = issue["item_id"].as_str() else {
                continue;
            };
            if let Some(item) = self.records.iter_mut().find(|item| item.id == item_id) {
                item.kind = "Audio".to_owned();
                fixed.push(issue_id.clone());
            }
        }
        if fixed.is_empty() {
            return Err("no fixable issues provided".to_owned());
        }
        let now = unix_timestamp();
        self.updated_at = now;
        let fixed_count = fixed.len();
        let job = LibraryRemediationJob {
            id: format!("library-remediation-{}", self.next_remediation_job_id),
            issue_ids: fixed,
            status: "completed".to_owned(),
            fixed_count,
            error: None,
            created_at: now,
            updated_at: now,
        };
        self.next_remediation_job_id = self.next_remediation_job_id.saturating_add(1).max(1);
        if self.remediation_jobs.len() == MAX_LIBRARY_REMEDIATION_JOBS {
            self.remediation_jobs.remove(0);
        }
        self.remediation_jobs.push(job.clone());
        Ok(job)
    }

    fn create(&mut self, artist: String, title: String, kind: String) -> Option<LibraryItemRecord> {
        if self.records.len() >= MAX_LIBRARY_ITEMS {
            return None;
        }
        let id = format!("lib-{}", self.allocate_id());
        let now = unix_timestamp();
        let record = LibraryItemRecord {
            id,
            artist,
            title,
            kind,
            created_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn allocate_id(&mut self) -> u64 {
        let mut candidate = self.next_id.max(1);
        for _ in 0..=self.records.len() {
            let id = format!("lib-{candidate}");
            if !self.records.iter().any(|record| record.id == id) {
                self.next_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded library store must leave an available u64 id")
    }

    fn allocate_health_scan_id(&mut self) -> u64 {
        let mut candidate = self.next_health_scan_id.max(1);
        for _ in 0..=self.health_scans.len() {
            let id = format!("scan-{candidate}");
            if !self.health_scans.iter().any(|record| record.id == id) {
                self.next_health_scan_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded library scan store must leave an available u64 id")
    }

    fn get(&self, id: &str) -> Option<LibraryItemRecord> {
        self.records.iter().find(|r| r.id == id).cloned()
    }

    fn delete(&mut self, id: &str) -> bool {
        if let Some(pos) = self.records.iter().position(|r| r.id == id) {
            self.records.remove(pos);
            self.updated_at = unix_timestamp();
            true
        } else {
            false
        }
    }

    fn json(&self) -> String {
        let records = self
            .records
            .iter()
            .map(LibraryItemRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"items\":[{}],\"count\":{},\"updated_at\":{}}}",
            records,
            self.records.len(),
            self.updated_at
        )
    }

    fn health_issues(&self) -> Vec<serde_json::Value> {
        self.records
            .iter()
            .flat_map(|item| {
                let mut issues = Vec::new();
                if item.artist.trim().is_empty() {
                    issues.push(serde_json::json!({
                        "id": format!("{}-missing-artist", item.id),
                        "item_id": item.id,
                        "artist": item.artist,
                        "title": item.title,
                        "type": "missing_artist",
                        "severity": "warning",
                        "message": "Library item has no artist",
                    }));
                }
                if item.title.trim().is_empty() {
                    issues.push(serde_json::json!({
                        "id": format!("{}-missing-title", item.id),
                        "item_id": item.id,
                        "artist": item.artist,
                        "title": item.title,
                        "type": "missing_title",
                        "severity": "warning",
                        "message": "Library item has no title",
                    }));
                }
                if item.kind.trim().is_empty() {
                    issues.push(serde_json::json!({
                        "id": format!("{}-missing-kind", item.id),
                        "item_id": item.id,
                        "artist": item.artist,
                        "title": item.title,
                        "type": "missing_kind",
                        "severity": "warning",
                        "message": "Library item has no media kind",
                    }));
                }
                issues
            })
            .collect()
    }

    fn fix_health_issues(&mut self) -> Vec<serde_json::Value> {
        let now = unix_timestamp();
        let mut fixed = Vec::new();
        for item in &mut self.records {
            if item.kind.trim().is_empty() {
                item.kind = "Audio".to_owned();
                fixed.push(serde_json::json!({
                    "id": format!("{}-missing-kind", item.id),
                    "item_id": item.id,
                    "type": "missing_kind",
                    "fixed": true,
                    "action": "defaulted_kind",
                    "kind": item.kind,
                }));
            }
        }
        if !fixed.is_empty() {
            self.updated_at = now;
        }
        fixed
    }

    fn patch_health_issue(
        &mut self,
        issue_id: &str,
        artist: Option<String>,
        title: Option<String>,
        kind: Option<String>,
    ) -> Option<serde_json::Value> {
        let issues = self.health_issues();
        let issue = issues
            .iter()
            .find(|issue| issue.get("id").and_then(serde_json::Value::as_str) == Some(issue_id))?;
        let item_id = issue.get("item_id")?.as_str()?.to_owned();
        let issue_type = issue.get("type")?.as_str()?.to_owned();
        let item = self.records.iter_mut().find(|item| item.id == item_id)?;
        let mut action = "unchanged";
        match issue_type.as_str() {
            "missing_artist" => {
                item.artist = truncate_utf8_bytes(
                    artist
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| "Unknown Artist".to_owned()),
                    MAX_LIST_ARTIST_BYTES,
                );
                action = "defaulted_artist";
            }
            "missing_title" => {
                item.title = truncate_utf8_bytes(
                    title
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| "Untitled".to_owned()),
                    MAX_LIST_TITLE_BYTES,
                );
                action = "defaulted_title";
            }
            "missing_kind" => {
                item.kind = truncate_utf8_bytes(
                    kind.filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| "Audio".to_owned()),
                    MAX_LIST_KIND_BYTES,
                );
                action = "defaulted_kind";
            }
            _ => {}
        }
        self.updated_at = unix_timestamp();
        Some(serde_json::json!({
            "id": issue_id,
            "item_id": item.id,
            "type": issue_type,
            "updated": true,
            "fixed": action != "unchanged",
            "action": action,
            "item": serde_json::from_str::<serde_json::Value>(&item.json()).unwrap_or_else(|_| serde_json::json!({ "id": item.id })),
            "updated_at": self.updated_at,
        }))
    }

    fn health_summary_json(&self, library_path: String) -> String {
        self.health_summary_value(library_path).to_string()
    }

    fn health_summary_value(&self, library_path: String) -> serde_json::Value {
        let total_issues = self.health_issues().len();
        serde_json::json!({
            "libraryPath": library_path,
            "totalIssues": total_issues,
            "issuesOpen": total_issues,
            "issuesResolved": 0,
        })
    }

    fn health_api_issues(&self) -> Vec<serde_json::Value> {
        let mut issues = self
            .health_issues()
            .into_iter()
            .map(|issue| {
                let issue_id = issue
                    .get("id")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                let issue_kind = issue
                    .get("type")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("missing_metadata");
                let remediation = self.remediation_jobs.iter().find(|job| {
                    job.issue_ids.iter().any(|id| id == issue_id)
                });
                let detected_at = issue
                    .get("item_id")
                    .and_then(serde_json::Value::as_str)
                    .and_then(|item_id| self.records.iter().find(|item| item.id == item_id))
                    .and_then(|item| i64::try_from(item.created_at).ok())
                    .and_then(|timestamp| chrono::DateTime::from_timestamp(timestamp, 0))
                    .map(|timestamp| {
                        timestamp.to_rfc3339_opts(chrono::SecondsFormat::Millis, true)
                    })
                    .unwrap_or_else(|| chrono::DateTime::UNIX_EPOCH.to_rfc3339());
                serde_json::json!({
                    "issueId": issue_id,
                    "type": "MissingMetadata",
                    "severity": "Medium",
                    "filePath": "",
                    "musicBrainzRecordingId": "",
                    "musicBrainzReleaseId": "",
                    "artist": issue.get("artist").and_then(serde_json::Value::as_str).unwrap_or_default(),
                    "album": "",
                    "title": issue.get("title").and_then(serde_json::Value::as_str).unwrap_or_default(),
                    "reason": issue.get("message").and_then(serde_json::Value::as_str).unwrap_or("Library metadata is incomplete"),
                    "metadata": {
                        "itemId": issue.get("item_id").and_then(serde_json::Value::as_str).unwrap_or_default(),
                        "missingField": issue_kind,
                    },
                    "canAutoFix": issue_kind == "missing_kind",
                    "suggestedAction": "Review and complete the missing library metadata",
                    "remediationJobId": remediation.map(|job| job.id.clone()).unwrap_or_default(),
                    "status": if remediation.is_some() { "Resolved" } else { "Detected" },
                    "detectedAt": detected_at,
                    "resolvedAt": remediation
                        .map(|job| unix_seconds_rfc3339(job.updated_at))
                        .map_or(serde_json::Value::Null, serde_json::Value::String),
                    "resolvedBy": "",
                })
            })
            .collect::<Vec<_>>();
        issues.sort_by(|left, right| {
            right["detectedAt"]
                .as_str()
                .cmp(&left["detectedAt"].as_str())
                .then_with(|| left["issueId"].as_str().cmp(&right["issueId"].as_str()))
        });
        issues
    }

    fn health_issues_json(&self, filter: &LibraryHealthIssueQuery) -> String {
        let issues =
            self.health_api_issues()
                .into_iter()
                .filter(|issue| {
                    (filter.types.is_empty()
                        || filter
                            .types
                            .iter()
                            .any(|value| value == issue["type"].as_str().unwrap_or_default()))
                        && (filter.severities.is_empty()
                            || filter.severities.iter().any(|value| {
                                value == issue["severity"].as_str().unwrap_or_default()
                            }))
                        && (filter.statuses.is_empty()
                            || filter
                                .statuses
                                .iter()
                                .any(|value| value == issue["status"].as_str().unwrap_or_default()))
                        && (filter.musicbrainz_release_id.is_empty()
                            || filter.musicbrainz_release_id
                                == issue["musicBrainzReleaseId"].as_str().unwrap_or_default())
                })
                .collect::<Vec<_>>();
        let total_count = issues.len();
        let issues = issues
            .into_iter()
            .skip(filter.offset)
            .take(filter.limit)
            .collect::<Vec<_>>();
        serde_json::json!({
            "issues": issues,
            "totalCount": total_count,
            "filter": {
                "libraryPath": filter.library_path,
                "types": filter.types,
                "severities": filter.severities,
                "statuses": filter.statuses,
                "musicBrainzReleaseId": filter.musicbrainz_release_id,
                "limit": filter.limit,
                "offset": filter.offset,
            },
        })
        .to_string()
    }

    fn health_issue_type_summaries(&self) -> Vec<serde_json::Value> {
        let count = self.health_issues().len();
        if count == 0 {
            Vec::new()
        } else {
            vec![serde_json::json!({
                "type": "MissingMetadata",
                "count": count,
                "bySeverity": { "Medium": count },
            })]
        }
    }

    fn health_issue_artist_summaries(&self, limit: usize) -> Vec<serde_json::Value> {
        let mut grouped = std::collections::BTreeMap::<String, usize>::new();
        for issue in self.health_issues() {
            let Some(artist) = issue
                .get("artist")
                .and_then(serde_json::Value::as_str)
                .filter(|artist| !artist.trim().is_empty())
            else {
                continue;
            };
            let artist = artist.to_owned();
            *grouped.entry(artist).or_default() += 1;
        }
        let mut rows = grouped
            .into_iter()
            .map(|(artist, count)| {
                serde_json::json!({
                    "artist": artist,
                    "count": count,
                    "byType": { "MissingMetadata": count },
                })
            })
            .collect::<Vec<_>>();
        rows.sort_by(|left, right| {
            right["count"]
                .as_u64()
                .cmp(&left["count"].as_u64())
                .then_with(|| left["artist"].as_str().cmp(&right["artist"].as_str()))
        });
        rows.truncate(limit);
        rows
    }

    fn health_issues_by_artist_json(&self, limit: usize) -> String {
        let rows = self.health_issue_artist_summaries(limit);
        let total_artists = rows.len();
        serde_json::json!({
            "groups": rows,
            "totalArtists": total_artists,
        })
        .to_string()
    }

    fn health_issues_by_release_json(&self, limit: usize) -> String {
        let mut grouped = BTreeMap::<(String, String), usize>::new();
        for item in &self.records {
            let count = [
                item.artist.trim().is_empty(),
                item.title.trim().is_empty(),
                item.kind.trim().is_empty(),
            ]
            .into_iter()
            .filter(|missing| *missing)
            .count();
            if count > 0 && !item.title.trim().is_empty() {
                *grouped
                    .entry((item.artist.clone(), item.title.clone()))
                    .or_default() += count;
            }
        }
        let mut rows = grouped
            .into_iter()
            .map(|((artist, album), count)| {
                serde_json::json!({
                    "artist": artist,
                    "album": album,
                    "musicBrainzReleaseId": "",
                    "count": count,
                    "byType": { "MissingMetadata": count },
                })
            })
            .collect::<Vec<_>>();
        rows.sort_by(|left, right| {
            right["count"]
                .as_u64()
                .cmp(&left["count"].as_u64())
                .then_with(|| left["artist"].as_str().cmp(&right["artist"].as_str()))
                .then_with(|| left["album"].as_str().cmp(&right["album"].as_str()))
        });
        rows.truncate(limit);
        let total_releases = rows.len();
        serde_json::json!({
            "groups": rows,
            "totalReleases": total_releases,
        })
        .to_string()
    }

    fn health_issues_by_type_json(&self, issue_type: Option<&str>) -> String {
        let rows = if issue_type.is_some_and(|requested| {
            !requested.eq_ignore_ascii_case("MissingMetadata") && !requested.starts_with("missing_")
        }) {
            Vec::new()
        } else {
            self.health_issue_type_summaries()
        };
        let total_issues = rows
            .iter()
            .filter_map(|row| row.get("count").and_then(serde_json::Value::as_u64))
            .sum::<u64>();
        serde_json::json!({
            "groups": rows,
            "totalIssues": total_issues,
        })
        .to_string()
    }

    fn health_dashboard_json(
        &self,
        library_path: String,
        artist_limit: usize,
        issue_limit: usize,
    ) -> String {
        let issues = self.health_api_issues();
        let total_issues = issues.len();
        serde_json::json!({
            "summary": self.health_summary_value(library_path),
            "issuesByType": self.health_issue_type_summaries(),
            "issuesByArtist": self.health_issue_artist_summaries(artist_limit),
            "issues": issues.into_iter().take(issue_limit).collect::<Vec<_>>(),
            "totalIssues": total_issues,
        })
        .to_string()
    }

    fn health_issues_by_codec_json(&self) -> String {
        let total_issues = self.health_issues().len();
        let groups = if total_issues == 0 {
            Vec::new()
        } else {
            vec![serde_json::json!({
                "codec": "UNKNOWN",
                "count": total_issues,
                "transcodeSuspect": 0,
            })]
        };
        serde_json::json!({ "groups": groups, "totalIssues": total_issues }).to_string()
    }

    fn musicbrainz_completion_json(&self) -> String {
        let mut grouped = std::collections::BTreeMap::<String, (usize, usize)>::new();
        for item in &self.records {
            let artist = if item.artist.trim().is_empty() {
                "(unknown)"
            } else {
                item.artist.as_str()
            };
            let entry = grouped.entry(artist.to_owned()).or_default();
            entry.0 += 1;
            if !item.title.trim().is_empty() {
                entry.1 += 1;
            }
        }
        let rows = grouped
            .into_iter()
            .map(|(artist, (total, complete))| {
                let completion = if total == 0 {
                    0.0
                } else {
                    complete as f64 / total as f64
                };
                serde_json::json!({
                    "artist": artist,
                    "items": total,
                    "complete": complete,
                    "completion": completion,
                })
            })
            .collect::<Vec<_>>();
        let average = if rows.is_empty() {
            0.0
        } else {
            rows.iter()
                .filter_map(|row| row.get("completion").and_then(serde_json::Value::as_f64))
                .sum::<f64>()
                / rows.len() as f64
        };
        serde_json::json!({
            "completion_status": rows,
            "average_completion": average,
            "count": rows.len(),
            "updated_at": self.updated_at,
        })
        .to_string()
    }

    fn discography_coverage_json(&self, artist: &str) -> String {
        let releases = self
            .records
            .iter()
            .filter(|item| item.artist.eq_ignore_ascii_case(artist))
            .count();
        serde_json::json!({
            "artist": artist,
            "coverage": if releases == 0 { 0.0 } else { 1.0 },
            "releases": releases,
            "updated_at": self.updated_at,
        })
        .to_string()
    }

    fn target_json(&self, target: &str) -> String {
        let rows = self
            .records
            .iter()
            .filter(|item| item.artist.eq_ignore_ascii_case(target) || item.id == target)
            .map(|item| {
                serde_json::json!({
                    "id": item.id,
                    "artist": item.artist,
                    "title": item.title,
                    "kind": item.kind,
                    "created_at": item.created_at,
                })
            })
            .collect::<Vec<_>>();
        serde_json::json!({
            "target": target,
            "items": rows,
            "count": rows.len(),
            "updated_at": self.updated_at,
        })
        .to_string()
    }
}

fn songid_matches_value(
    library: &LibraryStore,
    shares: &ShareIndexSnapshot,
    query: Option<&str>,
) -> Vec<serde_json::Value> {
    library
        .records
        .iter()
        .flat_map(|item| {
            shares.entries.iter().filter_map(move |entry| {
                let filename_score = songid_scoring::filename_identity_score(
                    &item.artist,
                    &item.title,
                    &entry.filename,
                );
                let query_score = query
                    .filter(|query| !query.trim().is_empty())
                    .map(|query| songid_scoring::compare_loose_text(query, &entry.filename))
                    .unwrap_or(0.0);
                let score = if query_score > 0.0 {
                    (filename_score * 0.75 + query_score * 0.25).min(1.0)
                } else {
                    filename_score
                };
                if score < 0.15 {
                    return None;
                }
                let normalized_filename = songid_scoring::normalize_loose_text(&entry.filename);
                let normalized_artist = songid_scoring::normalize_loose_text(&item.artist);
                let normalized_title = songid_scoring::normalize_loose_text(&item.title);
                let artist_similarity =
                    songid_scoring::compare_loose_text(&item.artist, &entry.filename);
                let title_similarity =
                    songid_scoring::compare_loose_text(&item.title, &entry.filename);
                let artist_match = !normalized_artist.is_empty()
                    && normalized_filename.contains(&normalized_artist);
                let title_match = !normalized_title.is_empty()
                    && normalized_filename.contains(&normalized_title);
                let mut signals = Vec::new();
                if artist_match {
                    signals.push("artist");
                }
                if title_match {
                    signals.push("title");
                }
                if entry.extension.eq_ignore_ascii_case("flac")
                    || entry.extension.eq_ignore_ascii_case("wav")
                    || entry.extension.eq_ignore_ascii_case("alac")
                {
                    signals.push("lossless_extension");
                }
                Some(serde_json::json!({
                    "libraryItemId": item.id,
                    "artist": item.artist,
                    "title": item.title,
                    "filename": entry.filename,
                    "extension": entry.extension,
                    "size": entry.size,
                    "score": score,
                    "identityScore": score,
                    "actionScore": (score * 0.75
                        + if entry.extension.eq_ignore_ascii_case("flac")
                            || entry.extension.eq_ignore_ascii_case("wav")
                            || entry.extension.eq_ignore_ascii_case("alac")
                        {
                            0.25
                        } else {
                            0.0
                        })
                        .min(1.0),
                    "artistSimilarity": artist_similarity,
                    "titleSimilarity": title_similarity,
                    "querySimilarity": query_score,
                    "signals": signals,
                    "source": "share-index",
                }))
            })
        })
        .collect()
}

/// Matches the oracle's `SongIdService.DetectSourceType` classification. The
/// source can still fall back to a text query when optional metadata tools are
/// unavailable, but the run must retain its actual source family.
fn songid_source_type(source: &str) -> &'static str {
    let lower = source.trim().to_ascii_lowercase();
    if Path::new(source.trim()).is_file() {
        return "local_file";
    }
    if (lower.starts_with("http://") || lower.starts_with("https://"))
        && (lower.contains("youtube.com/") || lower.contains("youtu.be/"))
    {
        return "youtube_url";
    }
    if lower.starts_with("spotify:track:")
        || ((lower.starts_with("http://") || lower.starts_with("https://"))
            && lower.contains("open.spotify.com/track/"))
    {
        return "spotify_url";
    }
    if reqwest::Url::parse(source.trim()).is_ok() {
        return "url";
    }
    "text_query"
}

fn songid_fallback_query(source: &str, source_type: &str) -> String {
    if source_type == "local_file" {
        return Path::new(source.trim())
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or_default()
            .trim()
            .to_owned();
    }
    source.trim().to_owned()
}

fn songid_spotify_metadata_from_html(source: &str, html: &str) -> serde_json::Value {
    let title = [metadata_value(html, "og:title"), metadata_title(html)]
        .into_iter()
        .find(|value| !value.trim().is_empty())
        .unwrap_or_default()
        .trim()
        .to_owned();
    let description = metadata_value(html, "og:description");
    let description_parts = description
        .split('·')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    let artist = description_parts.first().copied().unwrap_or_default();
    let album = description_parts.get(1).copied().unwrap_or_default();
    let query = match (artist, title.as_str()) {
        (artist, title) if !artist.is_empty() && !title.is_empty() => {
            format!("{artist} - {title}")
        }
        (_, title) if !title.is_empty() => title.to_owned(),
        (artist, _) => artist.to_owned(),
    };
    let source_id = source
        .split_once("/track/")
        .map(|(_, id)| id.split(['?', '#']).next().unwrap_or_default().trim())
        .filter(|id| !id.is_empty())
        .unwrap_or_default();
    serde_json::json!({
        "query": query,
        "metadata": {
            "title": title,
            "artist": artist,
            "album": album,
            "spotifyTrackId": source_id,
            "previewUrl": metadata_value(html, "og:audio"),
            "extra": {"analysisAudioSource": "spotify_page"},
        },
        "evidence": [format!("Spotify page metadata extracted query: {query}")],
    })
}

async fn songid_fetch_spotify_page_metadata(source: &str) -> Result<serde_json::Value, String> {
    let url =
        reqwest::Url::parse(source).map_err(|error| format!("Spotify URL is invalid: {error}"))?;
    if !matches!(url.scheme(), "http" | "https")
        || !url
            .host_str()
            .is_some_and(|host| host.eq_ignore_ascii_case("open.spotify.com"))
        || !url.username().is_empty()
        || url.password().is_some()
        || url.fragment().is_some()
    {
        return Err("Spotify URL is not a public open.spotify.com page".to_owned());
    }
    let host = url
        .host_str()
        .ok_or_else(|| "Spotify URL has no host".to_owned())?;
    let port = url
        .port_or_known_default()
        .ok_or_else(|| "Spotify URL port is unknown".to_owned())?;
    let addresses = (host, port)
        .to_socket_addrs()
        .map_err(|error| format!("Spotify URL resolution failed: {error}"))?
        .collect::<Vec<_>>();
    if addresses.is_empty()
        || addresses
            .iter()
            .any(|address| is_blocked_integration_ip(address.ip()))
    {
        return Err("Spotify URL resolves to a private address".to_owned());
    }
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .redirect(reqwest::redirect::Policy::none())
        .resolve_to_addrs(host, &addresses)
        .build()
        .map_err(|error| format!("failed to build Spotify metadata client: {error}"))?;
    let response = client
        .get(url)
        .header("User-Agent", "slskR-songid/1.0")
        .header(reqwest::header::ACCEPT, "text/html")
        .send()
        .await
        .map_err(|error| format!("Spotify metadata request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!(
            "Spotify metadata returned HTTP {}",
            response.status()
        ));
    }
    let body = read_bounded_source_provider_bytes(response, "Spotify metadata").await?;
    let html = String::from_utf8_lossy(&body);
    Ok(songid_spotify_metadata_from_html(source, &html))
}

async fn songid_run_tool(
    command: &mut tokio::process::Command,
    label: &str,
) -> Result<std::process::Output, String> {
    let output = tokio::time::timeout(Duration::from_secs(30), command.output())
        .await
        .map_err(|_| format!("{label} timed out"))?
        .map_err(|error| format!("{label} failed to start: {error}"))?;
    if output.stdout.len() > MAX_SONGID_TOOL_OUTPUT_BYTES
        || output.stderr.len() > MAX_SONGID_TOOL_OUTPUT_BYTES
    {
        return Err(format!(
            "{label} output exceeds {MAX_SONGID_TOOL_OUTPUT_BYTES} bytes"
        ));
    }
    Ok(output)
}

fn songid_parse_fpcalc_output(output: &str) -> Option<String> {
    output.lines().map(str::trim).find_map(|line| {
        if let Some(fingerprint) = line.strip_prefix("FINGERPRINT=") {
            return (!fingerprint.trim().is_empty()).then(|| fingerprint.trim().to_owned());
        }
        if line.is_empty() || line.starts_with("DURATION=") {
            return None;
        }
        Some(line.to_owned())
    })
}

async fn songid_extract_chromaprint(
    source: &str,
    settings: &ChromaprintIntegrationSettings,
) -> Result<String, String> {
    if !settings.enabled {
        return Err("Chromaprint is disabled".to_owned());
    }
    let source_path = Path::new(source);
    if !source_path.is_file() {
        return Err("local SongID source is not a file".to_owned());
    }

    // The target feeds ffmpeg's bounded, normalized PCM output into the
    // native Chromaprint service. This host exposes the same library through
    // fpcalc, so normalize through the configured ffmpeg first and invoke
    // fpcalc on that bounded WAV. This also keeps the configured decoder path
    // meaningful instead of silently using an unrelated decoder.
    let normalized_path = std::env::temp_dir().join(format!(
        "slskr-songid-{}.wav",
        uuid::Uuid::new_v4().simple()
    ));
    let result = async {
        let mut ffmpeg = tokio::process::Command::new(&settings.ffmpeg_path);
        ffmpeg
            .arg("-hide_banner")
            .arg("-nostdin")
            .arg("-loglevel")
            .arg("error")
            .arg("-y")
            .arg("-t")
            .arg(settings.duration_seconds.to_string())
            .arg("-i")
            .arg(source_path)
            .arg("-f")
            .arg("wav")
            .arg("-acodec")
            .arg("pcm_s16le")
            .arg("-ar")
            .arg(settings.sample_rate.to_string())
            .arg("-ac")
            .arg(settings.channels.to_string())
            .arg(&normalized_path)
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .kill_on_drop(true);
        let ffmpeg_output = songid_run_tool(&mut ffmpeg, "ffmpeg SongID normalization").await?;
        if !ffmpeg_output.status.success() {
            let stderr = String::from_utf8_lossy(&ffmpeg_output.stderr);
            return Err(format!(
                "ffmpeg exited with {}: {}",
                ffmpeg_output.status,
                stderr.trim().chars().take(512).collect::<String>()
            ));
        }

        let metadata = fs::metadata(&normalized_path)
            .map_err(|error| format!("normalized SongID audio is unavailable: {error}"))?;
        let max_pcm_bytes = u64::from(settings.sample_rate)
            .checked_mul(u64::from(settings.channels))
            .and_then(|value| value.checked_mul(u64::from(settings.duration_seconds)))
            .and_then(|value| value.checked_mul(2))
            .ok_or_else(|| "Chromaprint PCM size overflow".to_owned())?;
        if metadata.len() == 0 || metadata.len() > max_pcm_bytes.saturating_add(4096) {
            return Err("normalized SongID audio exceeded its bounded duration".to_owned());
        }

        let mut fpcalc = tokio::process::Command::new("fpcalc");
        fpcalc
            .arg("-plain")
            .arg("-algorithm")
            .arg(settings.algorithm.to_string())
            .arg("-length")
            .arg(settings.duration_seconds.to_string())
            .arg("-rate")
            .arg(settings.sample_rate.to_string())
            .arg("-channels")
            .arg(settings.channels.to_string())
            .arg(&normalized_path)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true);
        let fpcalc_output = songid_run_tool(&mut fpcalc, "fpcalc").await?;
        if !fpcalc_output.status.success() {
            let stderr = String::from_utf8_lossy(&fpcalc_output.stderr);
            return Err(format!(
                "fpcalc exited with {}: {}",
                fpcalc_output.status,
                stderr.trim().chars().take(512).collect::<String>()
            ));
        }
        let stdout = String::from_utf8_lossy(&fpcalc_output.stdout);
        songid_parse_fpcalc_output(&stdout)
            .ok_or_else(|| "fpcalc returned no Chromaprint fingerprint".to_owned())
    }
    .await;
    let _ = fs::remove_file(&normalized_path);
    result
}

async fn songid_acoustid_lookup(
    fingerprint: &str,
    settings: &AcoustIdIntegrationSettings,
    sample_rate: u32,
    duration_seconds: u32,
) -> Result<Option<serde_json::Value>, String> {
    if !settings.enabled {
        return Ok(None);
    }
    let client_id = settings
        .client_id
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| "AcoustID is enabled without a client id".to_owned())?;
    let base_url = reqwest::Url::parse(&settings.base_url)
        .map_err(|error| format!("AcoustID URL is invalid: {error}"))?;
    let resolved = validate_lidarr_base_url(base_url.as_str())
        .map_err(|error| format!("AcoustID URL is invalid: {error}"))?;
    let endpoint = format!("{}/lookup", base_url.as_str().trim_end_matches('/'));
    let url = reqwest::Url::parse(&endpoint)
        .map_err(|error| format!("AcoustID URL is invalid: {error}"))?;
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(20))
        .redirect(reqwest::redirect::Policy::none())
        .resolve_to_addrs(&resolved.host, &resolved.addrs)
        .build()
        .map_err(|error| format!("failed to build AcoustID client: {error}"))?;
    let duration = duration_seconds.to_string();
    let sample_rate = sample_rate.to_string();
    let response = client
        .post(url)
        .form(&[
            ("client", client_id),
            ("format", "json"),
            ("fingerprint", fingerprint),
            ("duration", duration.as_str()),
            ("sample_rate", sample_rate.as_str()),
            ("meta", "recordings"),
        ])
        .send()
        .await
        .map_err(|error| format!("AcoustID lookup failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("AcoustID returned HTTP {}", response.status()));
    }
    let root = read_bounded_source_provider_json(response, "AcoustID lookup").await?;
    Ok(root
        .get("results")
        .and_then(serde_json::Value::as_array)
        .and_then(|results| results.first())
        .cloned())
}

fn songid_acoustid_finding(result: &serde_json::Value) -> serde_json::Value {
    let recording = result
        .get("recordings")
        .and_then(serde_json::Value::as_array)
        .and_then(|recordings| recordings.first());
    let recording_id = recording
        .and_then(|recording| recording.get("id"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let title = recording
        .and_then(|recording| recording.get("title"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let artist = recording
        .and_then(|recording| recording.get("artists"))
        .and_then(serde_json::Value::as_array)
        .and_then(|artists| artists.first())
        .and_then(|artist| artist.get("name"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let score = result
        .get("score")
        .and_then(serde_json::Value::as_f64)
        .unwrap_or(0.0);
    serde_json::json!({
        "recordingId": recording_id,
        "externalId": result.get("id").cloned().unwrap_or(serde_json::Value::Null),
        "title": title,
        "artist": artist,
        "score": score,
        "summary": format!("AcoustID score {score:.2}"),
    })
}

async fn songid_source_analysis(
    source: &str,
    source_type: &str,
    integrations: &IntegrationSettings,
) -> (
    String,
    serde_json::Value,
    Vec<String>,
    Option<serde_json::Value>,
    Option<serde_json::Value>,
) {
    if source_type == "spotify_url" {
        if let Some(metadata) = tokio::time::timeout(
            Duration::from_secs(10),
            songid_fetch_spotify_page_metadata(source),
        )
        .await
        .ok()
        .and_then(Result::ok)
        {
            let query = metadata
                .get("query")
                .and_then(serde_json::Value::as_str)
                .filter(|query| !query.trim().is_empty())
                .unwrap_or(source)
                .to_owned();
            let run_metadata = metadata
                .get("metadata")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({}));
            let evidence = metadata
                .get("evidence")
                .and_then(serde_json::Value::as_array)
                .map(|values| {
                    values
                        .iter()
                        .filter_map(serde_json::Value::as_str)
                        .map(str::to_owned)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            return (query, run_metadata, evidence, None, None);
        }
    }

    let query = songid_fallback_query(source, source_type);
    let mut evidence = match source_type {
        "local_file" => vec![format!("Local file path detected: {source}")],
        "youtube_url" => vec!["YouTube URL detected; using source query fallback.".to_owned()],
        "spotify_url" => {
            vec!["Spotify metadata fetch failed; using source query fallback.".to_owned()]
        }
        "url" => vec!["URL detected; using source query fallback.".to_owned()],
        _ => vec!["Treating input as a direct SongID text query.".to_owned()],
    };
    let metadata = serde_json::json!({
        "title": if source_type == "local_file" { query.clone() } else { String::new() },
        "artist": "",
        "album": "",
        "extra": {"analysisAudioSource": source_type},
    });
    let mut full_source_fingerprint = None;
    let mut acoustid_finding = None;
    if source_type == "local_file" && integrations.chromaprint.enabled {
        match songid_extract_chromaprint(source, &integrations.chromaprint).await {
            Ok(fingerprint) => {
                evidence.push(format!(
                    "Chromaprint fingerprint extracted ({} characters).",
                    fingerprint.len()
                ));
                if integrations.acoustid.enabled {
                    match songid_acoustid_lookup(
                        &fingerprint,
                        &integrations.acoustid,
                        integrations.chromaprint.sample_rate,
                        integrations.chromaprint.duration_seconds,
                    )
                    .await
                    {
                        Ok(Some(result)) => {
                            let finding = songid_acoustid_finding(&result);
                            evidence.push("AcoustID returned a recording match.".to_owned());
                            acoustid_finding = Some(finding);
                        }
                        Ok(None) => {
                            evidence.push("AcoustID returned no recording match.".to_owned());
                        }
                        Err(error) => {
                            evidence.push(format!("AcoustID lookup failed: {error}"));
                        }
                    }
                }
                full_source_fingerprint = Some(serde_json::json!({
                    "path": "",
                    "durationSeconds": integrations.chromaprint.duration_seconds,
                    "fingerprintLength": fingerprint.len(),
                    "fingerprint": fingerprint,
                }));
            }
            Err(error) => evidence.push(format!("Chromaprint extraction failed: {error}")),
        }
    }
    (
        query,
        metadata,
        evidence,
        full_source_fingerprint,
        acoustid_finding,
    )
}

async fn enqueue_songid_job(
    state: &AppState,
    source: String,
    source_type: &str,
    requested_query: Option<String>,
    match_query: bool,
) -> Result<Option<routing::HttpResponse>, String> {
    let Some(sender) = state.songid_jobs.as_ref().cloned() else {
        return Ok(None);
    };

    let library = state.library.read().await;
    let shares = state.shares.read().await;
    let library_items = library.records.len();
    let shared_files = shares.entries.len();
    drop(shares);
    drop(library);

    let run = match mutate_runtime_compat_state(state, |runtime, _| {
        runtime.queue_songid_run(&source, source_type, library_items, shared_files)
    })
    .await
    {
        Ok(Some(run)) => run,
        Ok(None) => {
            return Ok(Some(routing::service_unavailable_response(
                "song id run space exhausted",
            )))
        }
        Err(error) => return Err(error),
    };
    let Some(run_id) = run.get("id").and_then(serde_json::Value::as_str) else {
        return Ok(Some(routing::service_unavailable_response(
            "song id run has no id",
        )));
    };
    publish_songid_hub_event(state, "create", &run);

    let job = SongIdJob {
        run_id: run_id.to_owned(),
        source,
        source_type: source_type.to_owned(),
        requested_query,
        match_query,
    };
    if sender.try_send(job).is_err() {
        if let Ok(Some(failed)) =
            mutate_runtime_compat_state(state, |runtime, _| runtime.fail_songid_run(run_id)).await
        {
            publish_songid_hub_event(state, "update", &failed);
        }
        return Ok(Some(routing::service_unavailable_response(
            "SongID run queue is unavailable",
        )));
    }
    Ok(Some(routing::accepted_response(run.to_string())))
}

fn spawn_songid_workers(state: Arc<AppState>, receiver: mpsc::Receiver<SongIdJob>) {
    let receiver = Arc::new(tokio::sync::Mutex::new(receiver));
    let worker_count = state
        .config
        .media_services
        .song_id_max_concurrent_runs
        .max(1);
    for _ in 0..worker_count {
        let state = Arc::clone(&state);
        let receiver = Arc::clone(&receiver);
        tokio::spawn(async move {
            loop {
                let job = receiver.lock().await.recv().await;
                let Some(job) = job else {
                    break;
                };
                let _permit = match Arc::clone(&state.songid_run_slots).acquire_owned().await {
                    Ok(permit) => permit,
                    Err(_) => {
                        fail_songid_run_with_reason(
                            &state,
                            &job.run_id,
                            "SongID worker pool is unavailable.",
                        )
                        .await;
                        break;
                    }
                };
                process_songid_job(&state, job).await;
            }
        });
    }
}

async fn process_songid_job(state: &AppState, job: SongIdJob) {
    match mutate_runtime_compat_state(state, |runtime, _| {
        runtime.update_songid_run(&job.run_id, |run| {
            run["status"] = serde_json::json!("running");
            run["summary"] = serde_json::json!("Starting SongID source analysis.");
            run["currentStage"] = serde_json::json!("source_analysis");
            run["percentComplete"] = serde_json::json!(0.12);
        })
    })
    .await
    {
        Ok(Some(run)) => publish_songid_hub_event(state, "update", &run),
        Ok(None) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "songid",
                format!("SongID run {} disappeared before processing", job.run_id),
            )
            .await;
            return;
        }
        Err(error) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "songid",
                format!("SongID run {} could not start: {error}", job.run_id),
            )
            .await;
            fail_songid_run_with_reason(
                state,
                &job.run_id,
                "SongID analysis could not be started.",
            )
            .await;
            return;
        }
    }

    let integrations = state.integration_settings.read().await.clone();
    let (fallback_query, metadata, evidence, full_source_fingerprint, acoustid_finding) =
        songid_source_analysis(&job.source, &job.source_type, &integrations).await;
    let query = job
        .requested_query
        .filter(|query| !query.trim().is_empty())
        .unwrap_or(fallback_query);

    let library = state.library.read().await;
    let shares = state.shares.read().await;
    let runs = songid_runs_value(
        &library,
        &shares,
        job.match_query.then_some(query.as_str()),
    );
    let matches = runs
        .iter()
        .flat_map(|run| {
            run.get("matches")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default()
        })
        .collect::<Vec<_>>();
    let library_items = library.records.len();
    let shared_files = shares.entries.len();
    drop(shares);
    drop(library);

    let spotify_metadata_loaded = metadata
        .pointer("/extra/analysisAudioSource")
        .and_then(serde_json::Value::as_str)
        == Some("spotify_page");
    let summary = match job.source_type.as_str() {
        "local_file" if full_source_fingerprint.is_some() && acoustid_finding.is_some() => {
            "Analyzed local file with Chromaprint and AcoustID metadata."
        }
        "local_file" if full_source_fingerprint.is_some() => {
            "Analyzed local file with Chromaprint and filename metadata."
        }
        "local_file" => "Analyzed local file with filename fallback metadata.",
        "youtube_url" => "Classified YouTube URL; optional metadata tools may enrich the run.",
        "spotify_url" if spotify_metadata_loaded => {
            "Analyzed Spotify page metadata for SongID query generation."
        }
        "spotify_url" => "Spotify metadata fetch failed; using source query fallback.",
        "url" => "Classified URL; optional source metadata may enrich the run.",
        _ => "Using free-text SongID query.",
    };
    match mutate_runtime_compat_state(state, |runtime, _| {
        runtime.complete_songid_run(
            &job.run_id,
            &job.source,
            &job.source_type,
            &query,
            matches,
            library_items,
            shared_files,
            summary,
            evidence,
            metadata,
            full_source_fingerprint,
            acoustid_finding,
        )
    })
    .await
    {
        Ok(Some(run)) => publish_songid_hub_event(state, "update", &run),
        Ok(None) => {}
        Err(error) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "songid",
                format!("SongID run {} completion persistence failed: {error}", job.run_id),
            )
            .await;
            fail_songid_run_with_reason(
                state,
                &job.run_id,
                "SongID analysis could not be completed.",
            )
            .await;
        }
    }
}

async fn fail_songid_run_with_reason(state: &AppState, run_id: &str, reason: &str) {
    match mutate_runtime_compat_state(state, |runtime, _| {
        runtime.fail_songid_run_with_reason(run_id, reason)
    })
    .await
    {
        Ok(Some(run)) => publish_songid_hub_event(state, "update", &run),
        Ok(None) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "songid",
                format!("SongID run {run_id} disappeared before failure was recorded"),
            )
            .await;
        }
        Err(error) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "songid",
                format!("SongID run {run_id} failure state could not be persisted: {error}"),
            )
            .await;
        }
    }
}

async fn requeue_persisted_songid_runs(state: &Arc<AppState>) {
    let Some(sender) = state.songid_jobs.as_ref().cloned() else {
        return;
    };
    let pending = {
        let runtime = state.runtime.read().await;
        runtime
            .songid_run_records
            .iter()
            .filter(|run| {
                matches!(
                    run.get("status").and_then(serde_json::Value::as_str),
                    Some("queued" | "running")
                )
            })
            .cloned()
            .collect::<Vec<_>>()
    };
    for run in pending {
        let Some(run_id) = run.get("id").and_then(serde_json::Value::as_str) else {
            continue;
        };
        let Some(source) = run.get("source").and_then(serde_json::Value::as_str) else {
            continue;
        };
        if source.trim().is_empty() {
            continue;
        }
        if run.get("status").and_then(serde_json::Value::as_str) == Some("running") {
            match mutate_runtime_compat_state(state, |runtime, _| {
                runtime.requeue_songid_run(run_id)
            })
            .await
            {
                Ok(Some(_)) => {}
                Ok(None) => {
                    record_daemon_log(
                        state,
                        logging::LogLevel::Warn,
                        "songid",
                        format!("persisted SongID run {run_id} disappeared during recovery"),
                    )
                    .await;
                    continue;
                }
                Err(error) => {
                    record_daemon_log(
                        state,
                        logging::LogLevel::Warn,
                        "songid",
                        format!("SongID run {run_id} recovery persistence failed: {error}"),
                    )
                    .await;
                    continue;
                }
            }
        }
        let job = SongIdJob {
            run_id: run_id.to_owned(),
            source: source.to_owned(),
            source_type: run
                .get("sourceType")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("text_query")
                .to_owned(),
            requested_query: run
                .get("query")
                .and_then(serde_json::Value::as_str)
                .filter(|query| !query.trim().is_empty())
                .map(str::to_owned),
            match_query: state.config.controller_profile != ControllerProfile::Native,
        };
        if sender.try_send(job).is_err() {
            match mutate_runtime_compat_state(state, |runtime, _| runtime.fail_songid_run(run_id))
                .await
            {
                Ok(Some(failed)) => publish_songid_hub_event(state, "update", &failed),
                Ok(None) => {
                    record_daemon_log(
                        state,
                        logging::LogLevel::Warn,
                        "songid",
                        format!("persisted SongID run {run_id} disappeared before queueing"),
                    )
                    .await;
                }
                Err(error) => {
                    record_daemon_log(
                        state,
                        logging::LogLevel::Warn,
                        "songid",
                        format!("SongID run {run_id} could not be marked failed: {error}"),
                    )
                    .await;
                }
            }
        }
    }
}

fn songid_path_is_within_root(path: &Path, root: &Path) -> bool {
    let Some(path) = normalize_absolute_path(path) else {
        return false;
    };
    let Some(root) = normalize_absolute_path(root) else {
        return false;
    };
    if !path.starts_with(&root) {
        return false;
    }
    canonicalize_with_missing_tail(&path)
        .zip(canonicalize_with_missing_tail(&root))
        .is_some_and(|(path, root)| path.starts_with(root))
}

/// Local SongID analysis is restricted to downloads, incomplete files, and
/// configured shares, matching the oracle's safe-root check. This is only
/// applied to an existing file; text and URL sources are not filesystem paths.
fn songid_local_file_is_allowed(config: &AppConfig, source: &str) -> bool {
    let path = Path::new(source.trim());
    if !path.is_file() {
        return false;
    }
    std::iter::once(config.downloads_dir.as_path())
        .chain(std::iter::once(config.incomplete_dir.as_path()))
        .chain(
            config
                .share_settings
                .directories
                .iter()
                .map(|directory| directory.local_path.as_path()),
        )
        .any(|root| songid_path_is_within_root(path, root))
}

fn songid_runs_value(
    library: &LibraryStore,
    shares: &ShareIndexSnapshot,
    query: Option<&str>,
) -> Vec<serde_json::Value> {
    let matches = songid_matches_value(library, shares, query);
    if library.records.is_empty() && shares.entries.is_empty() {
        return Vec::new();
    }
    let scores = matches
        .iter()
        .filter_map(|candidate| candidate.get("score").and_then(serde_json::Value::as_f64))
        .collect::<Vec<_>>();
    let consensus = songid_scoring::identity_consensus(&scores);
    let strongest = scores
        .iter()
        .copied()
        .fold(0.0_f64, f64::max);
    let candidate_text = matches
        .iter()
        .filter_map(|candidate| candidate.get("filename").and_then(serde_json::Value::as_str))
        .take(256)
        .collect::<Vec<_>>()
        .join("\n");
    let repeated_candidate_lines = songid_scoring::repeated_line_ratio(&candidate_text);
    let repeated_candidate_ngrams = songid_scoring::repeated_ngram_ratio(&candidate_text);
    let matrix = matches
        .iter()
        .take(100)
        .map(|candidate| {
            serde_json::json!({
                "libraryItemId": candidate.get("libraryItemId").cloned().unwrap_or(serde_json::Value::Null),
                "filename": candidate.get("filename").cloned().unwrap_or(serde_json::Value::Null),
                "score": candidate.get("score").cloned().unwrap_or(serde_json::json!(0.0)),
                "signals": candidate.get("signals").cloned().unwrap_or_else(|| serde_json::json!([])),
            })
        })
        .collect::<Vec<_>>();
    vec![serde_json::json!({
        "id": "songid-local",
        "status": "completed",
        "libraryItems": library.records.len(),
        "sharedFiles": shares.entries.len(),
        "matches": matches,
        "matchCount": scores.len(),
        "scorecard": {
            "candidateCount": scores.len(),
            "strongMatchCount": scores.iter().filter(|score| **score >= 0.75).count(),
            "identityConsensus": consensus,
            "highestIdentityScore": strongest,
        },
        "identityAssessment": {
            "verdict": if strongest >= 0.8 { "strong_identity" } else if strongest >= 0.45 { "candidate_identity" } else { "weak_identity" },
            "confidence": consensus,
            "summary": if scores.is_empty() { "No matching shared files were found." } else { "Shared-file metadata produced identity candidates." },
        },
        "forensicMatrix": matrix,
        "syntheticAssessment": {
            "verdict": "insufficient_evidence",
            "confidence": "low",
            "syntheticScore": 0.0,
            "identityScore": consensus,
            "candidateLineRepetition": repeated_candidate_lines,
            "candidateNgramRepetition": repeated_candidate_ngrams,
            "summary": "No audio forensic transcript or perturbation evidence was supplied.",
        },
        "updated_at": library.updated_at,
    })]
}

fn lidarr_missing_albums_value(library: &LibraryStore) -> Vec<serde_json::Value> {
    library
        .health_issues()
        .into_iter()
        .map(|issue| {
            let item_id = issue
                .get("item_id")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("unknown");
            serde_json::json!({
                "id": format!("lidarr-{item_id}"),
                "artist": issue.get("artist").cloned().unwrap_or_else(|| serde_json::json!("")),
                "title": issue.get("title").cloned().unwrap_or_else(|| serde_json::json!("")),
                "issueType": issue.get("type").cloned().unwrap_or_else(|| serde_json::json!("unknown")),
                "source": "library-health",
                "status": "missing_metadata",
                "item_id": item_id,
            })
        })
        .collect()
}

// Destination Models
#[derive(Clone, Debug)]
struct DestinationRecord {
    id: String,
    name: String,
    path: String,
    is_default: bool,
}

impl DestinationRecord {
    fn json(&self) -> String {
        serde_json::json!({
            "id": self.id,
            "name": self.name,
            "path": self.path,
            "isDefault": self.is_default,
            "is_default": self.is_default,
            "exists": std::path::Path::new(&self.path).exists(),
        })
        .to_string()
    }
}

#[derive(Debug)]
struct DestinationStore {
    records: Vec<DestinationRecord>,
}

impl DestinationStore {
    fn new() -> Self {
        Self {
            records: vec![DestinationRecord {
                id: "default".to_string(),
                name: "Default".to_string(),
                path: "/home/user/Downloads".to_string(),
                is_default: true,
            }],
        }
    }

    fn from_persisted(records: Vec<crate::persistence::DestinationRecord>) -> Self {
        if records.is_empty() {
            return Self::new();
        }
        let mut seen_ids = std::collections::HashSet::new();
        let mut records = records
            .into_iter()
            .filter(|record| seen_ids.insert(record.id.clone()))
            .take(MAX_DESTINATIONS)
            .map(|record| DestinationRecord {
                id: record.id,
                name: record.name,
                path: record.path,
                is_default: record.is_default,
            })
            .collect::<Vec<_>>();
        let default_index = records
            .iter()
            .position(|record| record.is_default)
            .unwrap_or(0);
        for (index, record) in records.iter_mut().enumerate() {
            record.is_default = index == default_index;
        }
        records.sort_by(|left, right| {
            right
                .is_default
                .cmp(&left.is_default)
                .then_with(|| left.name.cmp(&right.name))
                .then_with(|| left.id.cmp(&right.id))
        });
        Self { records }
    }

    fn from_config(
        downloads_dir: &Path,
        configured: &[crate::config::DestinationSettings],
    ) -> Self {
        let downloads = downloads_dir.display().to_string();
        let mut records = vec![DestinationRecord {
            id: "default".to_owned(),
            name: "Downloads".to_owned(),
            path: downloads.clone(),
            is_default: !configured.iter().any(|destination| destination.default),
        }];
        records.extend(
            configured
                .iter()
                .enumerate()
                .filter_map(|(index, destination)| {
                    let path = destination.path.display().to_string();
                    (path != downloads).then(|| DestinationRecord {
                        id: format!("configured-{index}"),
                        name: if destination.name.trim().is_empty() {
                            destination
                                .path
                                .file_name()
                                .and_then(|name| name.to_str())
                                .unwrap_or(path.as_str())
                                .to_owned()
                        } else {
                            destination.name.clone()
                        },
                        path,
                        is_default: destination.default,
                    })
                }),
        );
        Self { records }
    }

    fn list(&self) -> String {
        let records = self
            .records
            .iter()
            .map(|record| {
                serde_json::from_str::<serde_json::Value>(&record.json()).unwrap_or_default()
            })
            .collect::<Vec<_>>();
        serde_json::Value::Array(records).to_string()
    }

    fn versioned_record_value(record: &DestinationRecord) -> serde_json::Value {
        serde_json::json!({
            "name": if record.id == "default" && record.name == "Default" {
                "Downloads"
            } else {
                record.name.as_str()
            },
            "path": record.path,
            "isDefault": record.is_default,
            "exists": std::path::Path::new(&record.path).exists(),
        })
    }

    fn versioned_list(&self) -> String {
        serde_json::Value::Array(
            self.records
                .iter()
                .map(Self::versioned_record_value)
                .collect(),
        )
        .to_string()
    }

    fn versioned_default(&self) -> String {
        let record = self
            .records
            .iter()
            .find(|record| record.is_default)
            .unwrap_or(&self.records[0]);
        Self::versioned_record_value(record).to_string()
    }

    fn default(&self) -> String {
        self.records
            .iter()
            .find(|record| record.is_default)
            .unwrap_or(&self.records[0])
            .json()
    }

    fn normalize_explicit_path(&self, requested: &str) -> Option<PathBuf> {
        let requested = Path::new(requested.trim());
        if !requested.is_absolute() {
            return None;
        }
        let mut normalized = PathBuf::new();
        for component in requested.components() {
            match component {
                Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
                Component::RootDir => normalized.push(std::path::MAIN_SEPARATOR.to_string()),
                Component::CurDir => {}
                Component::ParentDir => {
                    if !normalized.pop() {
                        return None;
                    }
                }
                Component::Normal(value) => normalized.push(value),
            }
        }
        if !normalized.is_absolute() {
            return None;
        }

        self.records
            .iter()
            .any(|record| {
                let root = Path::new(&record.path);
                let Some(root) = normalize_absolute_path(root) else {
                    return false;
                };
                if !normalized.starts_with(&root) {
                    return false;
                }
                canonicalize_with_missing_tail(&normalized)
                    .zip(canonicalize_with_missing_tail(&root))
                    .is_some_and(|(canonical_path, canonical_root)| {
                        canonical_path.starts_with(canonical_root)
                    })
            })
            .then_some(normalized)
    }
}

/// Resolve an absolute path through every existing ancestor and append any
/// missing tail. This preserves validation for destinations that will be
/// created later while still following symlinks in existing ancestors. Any
/// non-NotFound filesystem error is rejected by returning `None`.
fn canonicalize_with_missing_tail(path: &Path) -> Option<PathBuf> {
    let mut existing = path;
    let mut missing = Vec::new();
    loop {
        match existing.canonicalize() {
            Ok(mut canonical) => {
                for component in missing.iter().rev() {
                    canonical.push(component);
                }
                return Some(canonical);
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                let name = existing.file_name()?.to_os_string();
                missing.push(name);
                existing = existing.parent()?;
            }
            Err(_) => return None,
        }
    }
}

fn normalize_absolute_path(path: &Path) -> Option<PathBuf> {
    if !path.is_absolute() {
        return None;
    }
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            Component::RootDir => normalized.push(std::path::MAIN_SEPARATOR.to_string()),
            Component::CurDir => {}
            Component::ParentDir => {
                if !normalized.pop() {
                    return None;
                }
            }
            Component::Normal(value) => normalized.push(value),
        }
    }
    normalized.is_absolute().then_some(normalized)
}

fn directory_is_writable(path: &Path) -> bool {
    if !path.is_dir() {
        return false;
    }
    let probe = path.join(format!(
        ".slskr-write-test-{}",
        uuid::Uuid::new_v4().simple()
    ));
    let writable = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&probe)
        .is_ok();
    if writable {
        let _ = fs::remove_file(probe);
    }
    writable
}

#[derive(Clone, Debug)]
struct PreviewStreamTicket {
    family: String,
    source: String,
    content_id: String,
    filename: String,
    peer_username: Option<String>,
    size: u64,
    content_type: String,
    source_url: Option<String>,
    source_authorization: Option<String>,
    overlay_peer_identity: Option<String>,
    expected_hash: Option<String>,
    created_at: u64,
    expires_at: u64,
}

#[derive(Debug)]
struct PreviewStreamTicketStore {
    records: BTreeMap<String, PreviewStreamTicket>,
    max_records: usize,
}

const MAX_CONTROLLER_FEATURE_RECORDS: usize = 4_096;
const MAX_CONTROLLER_FEATURE_STATE_BYTES: u64 = 8 * 1024 * 1024;

#[derive(Debug, Deserialize, Serialize)]
struct ControllerFeatureStateFile {
    version: u32,
    records: BTreeMap<String, serde_json::Value>,
}

#[derive(Debug)]
struct ControllerFeatureState {
    records: BTreeMap<String, serde_json::Value>,
    state_path: PathBuf,
}

impl ControllerFeatureState {
    fn load(state_dir: &Path) -> Result<Self, String> {
        let state_path = state_dir.join("controller-feature-state.json");
        let records = if state_path.exists() {
            let metadata = fs::metadata(&state_path)
                .map_err(|error| format!("controller feature state metadata failed: {error}"))?;
            if metadata.len() > MAX_CONTROLLER_FEATURE_STATE_BYTES {
                return Err("controller feature state exceeds the 8 MiB limit".to_owned());
            }
            let bytes = fs::read(&state_path)
                .map_err(|error| format!("controller feature state read failed: {error}"))?;
            let file = serde_json::from_slice::<ControllerFeatureStateFile>(&bytes)
                .map_err(|error| format!("controller feature state parse failed: {error}"))?;
            if file.version != 1 || file.records.len() > MAX_CONTROLLER_FEATURE_RECORDS {
                return Err("controller feature state is unsupported or over capacity".to_owned());
            }
            file.records
        } else {
            BTreeMap::new()
        };
        Ok(Self {
            records,
            state_path,
        })
    }

    fn validate_storage(&self) -> Result<(), String> {
        let metadata = match fs::symlink_metadata(&self.state_path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(error) => {
                return Err(format!("controller feature state metadata failed: {error}"));
            }
        };
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err("controller feature state path must be a regular file".to_owned());
        }
        Ok(())
    }

    #[cfg(any(test, feature = "bounded-differential"))]
    fn in_memory() -> Self {
        let unique = uuid::Uuid::new_v4().simple().to_string();
        Self {
            records: BTreeMap::new(),
            state_path: std::env::temp_dir()
                .join(format!("slskr-controller-features-{unique}.json")),
        }
    }

    fn upsert(&mut self, key: String, value: serde_json::Value) -> Result<(), String> {
        if self.records.len() >= MAX_CONTROLLER_FEATURE_RECORDS && !self.records.contains_key(&key)
        {
            return Err("controller feature record capacity is full".to_owned());
        }
        let previous = self.records.insert(key.clone(), value);
        if let Err(error) = self.persist() {
            match previous {
                Some(previous) => {
                    self.records.insert(key, previous);
                }
                None => {
                    self.records.remove(&key);
                }
            }
            return Err(error);
        }
        Ok(())
    }

    fn remove(&mut self, key: &str) -> Result<Option<serde_json::Value>, String> {
        let removed = self.records.remove(key);
        if removed.is_some() {
            if let Err(error) = self.persist() {
                self.records
                    .insert(key.to_owned(), removed.clone().unwrap_or_default());
                return Err(error);
            }
        }
        Ok(removed)
    }

    fn get(&self, key: &str) -> Option<&serde_json::Value> {
        self.records.get(key)
    }

    fn values_with_prefix(&self, prefix: &str) -> Vec<serde_json::Value> {
        self.entries_with_prefix(prefix)
            .into_iter()
            .map(|(_, value)| value)
            .collect()
    }

    fn entries_with_prefix(&self, prefix: &str) -> Vec<(String, serde_json::Value)> {
        self.records
            .range(prefix.to_owned()..)
            .take_while(|(key, _)| key.starts_with(prefix))
            .map(|(key, value)| (key.clone(), value.clone()))
            .collect()
    }

    fn remove_keys(&mut self, keys: &[String]) -> Result<usize, String> {
        let previous = self.records.clone();
        let removed = keys
            .iter()
            .filter(|key| self.records.remove(key.as_str()).is_some())
            .count();
        if removed > 0 {
            if let Err(error) = self.persist() {
                self.records = previous;
                return Err(error);
            }
        }
        Ok(removed)
    }

    fn remove_prefix(&mut self, prefix: &str) -> Result<usize, String> {
        let previous = self.records.clone();
        let before = self.records.len();
        self.records.retain(|key, _| !key.starts_with(prefix));
        let removed = before.saturating_sub(self.records.len());
        if removed > 0 {
            if let Err(error) = self.persist() {
                self.records = previous;
                return Err(error);
            }
        }
        Ok(removed)
    }

    fn record_warm_cache_accesses(&mut self, content_ids: &[String]) -> Result<(), String> {
        let previous = self.records.clone();
        let now = unix_timestamp();
        for content_id in content_ids {
            let key = format!("warm-cache/popularity/{content_id}");
            let hits = self
                .records
                .get(&key)
                .and_then(|value| value.get("hits"))
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0)
                .saturating_add(1);
            if self.records.len() >= MAX_CONTROLLER_FEATURE_RECORDS
                && !self.records.contains_key(&key)
            {
                self.records = previous;
                return Err("warm cache popularity capacity is full".to_owned());
            }
            self.records.insert(
                key,
                serde_json::json!({
                    "contentId": content_id,
                    "hits": hits,
                    "lastUpdated": now,
                }),
            );
        }
        if let Err(error) = self.persist() {
            self.records = previous;
            return Err(error);
        }
        Ok(())
    }

    fn import_soulseek_interests(
        &mut self,
        username: &str,
        liked: &[String],
        hated: &[String],
    ) -> Result<(), String> {
        let issuer = format!("soulseek:{username}");
        let previous = self.records.clone();
        self.records.retain(|key, value| {
            !(key.starts_with("opinion/")
                && value.get("issuer").and_then(serde_json::Value::as_str) == Some(issuer.as_str())
                && value.get("source").and_then(serde_json::Value::as_str)
                    == Some("soulseek-interest"))
        });
        let now = unix_timestamp().saturating_mul(1000);
        for (kind, values) in [("Like", liked), ("Hate", hated)] {
            for interest in values.iter().take(MAX_INTERESTS_PER_KIND) {
                let interest = interest.trim();
                if interest.is_empty()
                    || interest.len() > MAX_INTEREST_NAME_BYTES
                    || interest.chars().any(char::is_control)
                {
                    continue;
                }
                let (subject_type, subject_id) = interest
                    .split_once(':')
                    .map(|(prefix, value)| {
                        let subject_type = match prefix.to_ascii_lowercase().as_str() {
                            "artist" => "Artist",
                            "album" => "Album",
                            "track" => "Track",
                            "user" => "User",
                            "file" => "File",
                            _ => "Track",
                        };
                        (subject_type, value.trim())
                    })
                    .unwrap_or(("Track", interest));
                if subject_id.is_empty() {
                    continue;
                }
                let id = uuid::Uuid::new_v4().to_string();
                if self.records.len() >= MAX_CONTROLLER_FEATURE_RECORDS {
                    self.records = previous;
                    return Err("opinion record capacity is full".to_owned());
                }
                self.records.insert(
                    format!("opinion/{id}"),
                    serde_json::json!({
                        "id": id,
                        "issuer": issuer,
                        "subjectType": subject_type,
                        "subjectId": subject_id,
                        "kind": kind,
                        "strength": 0.25,
                        "confidence": 0.25,
                        "scope": "soulseek-public",
                        "source": "soulseek-interest",
                        "reason": "Soulseek user interest",
                        "createdUnixMs": now,
                        "updatedUnixMs": now,
                    }),
                );
            }
        }
        if let Err(error) = self.persist() {
            self.records = previous;
            return Err(error);
        }
        Ok(())
    }

    fn persist(&self) -> Result<(), String> {
        let bytes = serde_json::to_vec(&ControllerFeatureStateFile {
            version: 1,
            records: self.records.clone(),
        })
        .map_err(|error| format!("controller feature state serialization failed: {error}"))?;
        if bytes.len() as u64 > MAX_CONTROLLER_FEATURE_STATE_BYTES {
            return Err("controller feature state exceeds the 8 MiB limit".to_owned());
        }
        write_file_atomic(&self.state_path, &bytes)
            .map_err(|error| format!("controller feature state write failed: {error}"))
    }
}

impl Default for PreviewStreamTicketStore {
    fn default() -> Self {
        Self::with_max_records(MAX_PREVIEW_STREAM_TICKETS)
    }
}

impl PreviewStreamTicketStore {
    fn with_max_records(max_records: usize) -> Self {
        Self {
            records: BTreeMap::new(),
            max_records: max_records.max(1),
        }
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "ticket fields are explicit at the single construction boundary"
    )]
    fn issue(
        &mut self,
        family: &str,
        source: &str,
        content_id: String,
        filename: String,
        peer_username: Option<String>,
        size: u64,
        content_type: String,
        ttl_seconds: u64,
    ) -> Option<(String, PreviewStreamTicket)> {
        let now = unix_timestamp();
        self.prune(now);
        if self.records.len() >= self.max_records {
            return None;
        }
        let token = secure_oauth_state()?;
        let record = PreviewStreamTicket {
            family: family.to_owned(),
            source: source.to_owned(),
            content_id,
            filename,
            peer_username,
            size,
            content_type,
            source_url: None,
            source_authorization: None,
            overlay_peer_identity: None,
            expected_hash: None,
            created_at: now,
            expires_at: now.saturating_add(ttl_seconds),
        };
        self.records.insert(token.clone(), record.clone());
        Some((token, record))
    }

    fn get(&mut self, token: &str) -> Option<PreviewStreamTicket> {
        let now = unix_timestamp();
        self.prune(now);
        self.records.get(token).cloned()
    }

    fn find_active_token(
        &mut self,
        family: &str,
        source: &str,
        content_id: &str,
    ) -> Option<String> {
        let now = unix_timestamp();
        self.prune(now);
        self.records
            .iter()
            .find(|(_, record)| {
                record.family == family
                    && record.source == source
                    && record.content_id == content_id
            })
            .map(|(token, _)| token.clone())
    }

    fn configure_remote_mesh(
        &mut self,
        token: &str,
        source_url: String,
        source_authorization: Option<String>,
        expected_hash: String,
    ) -> bool {
        let Some(record) = self.records.get_mut(token) else {
            return false;
        };
        record.source_url = Some(source_url);
        record.source_authorization = source_authorization;
        record.expected_hash = Some(expected_hash);
        true
    }

    fn configure_remote_overlay(
        &mut self,
        token: &str,
        peer_identity: String,
        expected_hash: String,
    ) -> bool {
        let Some(record) = self.records.get_mut(token) else {
            return false;
        };
        record.overlay_peer_identity = Some(peer_identity);
        record.expected_hash = Some(expected_hash);
        true
    }

    fn revoke_source(&mut self, source: &str) {
        self.records.retain(|_, record| record.source != source);
    }

    fn prune(&mut self, now: u64) {
        self.records.retain(|_, record| record.expires_at > now);
    }
}

#[derive(Debug, Default)]
struct ListeningPartyStreamLimits {
    parties: BTreeMap<String, Arc<Semaphore>>,
    per_ip: BTreeMap<String, Arc<Semaphore>>,
}

#[derive(Debug, Eq, PartialEq)]
enum ListeningPartyStreamLimitRejection {
    Party,
    Ip,
    Capacity,
}

impl ListeningPartyStreamLimits {
    fn try_acquire(
        &mut self,
        party_id: &str,
        remote_ip: &str,
    ) -> Result<(OwnedSemaphorePermit, OwnedSemaphorePermit), ListeningPartyStreamLimitRejection>
    {
        self.parties.retain(|_, semaphore| {
            semaphore.available_permits() < LISTED_PARTY_MAX_CONCURRENT_STREAMS
        });
        self.per_ip.retain(|_, semaphore| {
            semaphore.available_permits() < LISTED_PARTY_MAX_CONCURRENT_STREAMS_PER_IP
        });

        let party = if let Some(party) = self.parties.get(party_id) {
            Arc::clone(party)
        } else {
            if self.parties.len() >= MAX_LISTED_PARTY_STREAM_LIMITERS {
                return Err(ListeningPartyStreamLimitRejection::Capacity);
            }
            let party = Arc::new(Semaphore::new(LISTED_PARTY_MAX_CONCURRENT_STREAMS));
            self.parties.insert(party_id.to_owned(), Arc::clone(&party));
            party
        };
        let party_permit = party
            .try_acquire_owned()
            .map_err(|_| ListeningPartyStreamLimitRejection::Party)?;

        let ip_key = format!("{party_id}:{remote_ip}");
        let ip = if let Some(ip) = self.per_ip.get(&ip_key) {
            Arc::clone(ip)
        } else {
            if self.per_ip.len() >= MAX_LISTED_PARTY_STREAM_LIMITERS {
                return Err(ListeningPartyStreamLimitRejection::Capacity);
            }
            let ip = Arc::new(Semaphore::new(LISTED_PARTY_MAX_CONCURRENT_STREAMS_PER_IP));
            self.per_ip.insert(ip_key, Arc::clone(&ip));
            ip
        };
        let ip_permit = match ip.try_acquire_owned() {
            Ok(permit) => permit,
            Err(_) => {
                drop(party_permit);
                return Err(ListeningPartyStreamLimitRejection::Ip);
            }
        };
        Ok((party_permit, ip_permit))
    }
}

#[derive(Debug)]
struct DistributedRuntime {
    local_username: String,
    branch_level: u32,
    branch_root: String,
    parent: Option<String>,
    parent_sender: Option<mpsc::Sender<DistributedMessage>>,
    children: BTreeMap<String, mpsc::Sender<DistributedMessage>>,
    child_depths: BTreeMap<String, u32>,
}

impl DistributedRuntime {
    fn new(username: Option<&str>) -> Self {
        let local_username = username.unwrap_or_default().trim().to_owned();
        Self {
            branch_level: 0,
            branch_root: local_username.clone(),
            local_username,
            parent: None,
            parent_sender: None,
            children: BTreeMap::new(),
            child_depths: BTreeMap::new(),
        }
    }

    fn reset_branch(&mut self) {
        self.parent = None;
        self.parent_sender = None;
        self.branch_level = 0;
        self.branch_root.clone_from(&self.local_username);
    }

    fn child_depth(&self) -> u32 {
        self.child_depths
            .values()
            .copied()
            .map(|depth| depth.saturating_add(1))
            .max()
            .unwrap_or(0)
    }

    fn json(&self, settings: crate::config::SoulseekDistributedSettings) -> serde_json::Value {
        let mut children = self.children.keys().cloned().collect::<Vec<_>>();
        children.sort_unstable();
        serde_json::json!({
            "branchLevel": self.branch_level,
            "branchRoot": self.branch_root,
            "canAcceptChildren": !settings.disabled
                && !settings.disable_children
                && self.children.len() < settings.child_limit,
            "childLimit": settings.child_limit,
            "children": children,
            "hasParent": self.parent.is_some(),
            "isBranchRoot": self.parent.is_none(),
            "parent": self.parent,
        })
    }

    fn application_json(
        &self,
        settings: crate::config::SoulseekDistributedSettings,
        connected: bool,
        target: ControllerProfile,
    ) -> serde_json::Value {
        if connected {
            let mut value = self.json(settings);
            if target == ControllerProfile::Native && self.parent.is_none() {
                value["parent"] = serde_json::json!("");
            } else if self.parent.is_none() {
                value
                    .as_object_mut()
                    .expect("distributed application state must be an object")
                    .remove("parent");
            }
            return value;
        }
        let mut value = serde_json::json!({
            "branchLevel": 0,
            "canAcceptChildren": false,
            "childLimit": 0,
            "children": [],
            "hasParent": false,
            "isBranchRoot": false,
        });
        if target == ControllerProfile::Native {
            value["branchRoot"] = serde_json::json!("");
            value["parent"] = serde_json::json!("");
        }
        value
    }

    /// Load persisted distributed tree state
    pub async fn load_persisted_state(
        &mut self,
        db: &crate::persistence::DatabaseManager,
    ) -> Result<(), String> {
        if let Some((branch_level, branch_root, parent_username)) = db
            .load_distributed_tree_state()
            .await
            .map_err(|error| format!("failed to load distributed tree state: {error}"))?
        {
            self.branch_level = branch_level;
            self.branch_root = branch_root;
            self.parent = parent_username;
        }

        let children = db
            .load_distributed_children()
            .await
            .map_err(|error| format!("failed to load distributed child state: {error}"))?;
        self.child_depths = children.into_iter().collect();
        Ok(())
    }

    /// Save distributed tree state to database
    pub async fn save_persisted_state(
        &self,
        db: &crate::persistence::DatabaseManager,
    ) -> Result<(), String> {
        db
            .save_distributed_tree_state(
                self.branch_level,
                &self.branch_root,
                self.parent.as_deref(),
            )
            .await
            .map_err(|error| format!("failed to save distributed tree state: {error}"))?;

        let children: Vec<(String, u32)> = self
            .child_depths
            .iter()
            .map(|(username, depth)| (username.clone(), *depth))
            .collect();
        db.save_distributed_children(&children)
            .await
            .map_err(|error| format!("failed to save distributed child state: {error}"))?;
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DistributedConnectionRole {
    Parent,
    Child,
}

async fn record_distributed_persistence_failure(
    state: &AppState,
    operation: &str,
    error: String,
) {
    record_daemon_log(
        state,
        logging::LogLevel::Error,
        "distributed",
        format!("{operation}: {error}"),
    )
    .await;
}

fn resolve_external_visualizer_path(configured: Option<&str>) -> Option<PathBuf> {
    let configured = configured
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let path = Path::new(configured);
    if path.is_absolute() || path.components().count() > 1 {
        return path
            .is_file()
            .then(|| fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf()));
    }
    std::env::var_os("PATH")
        .into_iter()
        .flat_map(|value| std::env::split_paths(&value).collect::<Vec<_>>())
        .map(|directory| directory.join(configured))
        .find(|candidate| candidate.is_file())
}

fn path_directories() -> Vec<PathBuf> {
    std::env::var_os("PATH")
        .into_iter()
        .flat_map(|value| std::env::split_paths(&value).collect::<Vec<_>>())
        .collect()
}

fn command_exists_on_path(command: &str) -> bool {
    path_directories()
        .iter()
        .any(|directory| directory.join(command).is_file())
}

fn configured_command_exists(command: &str) -> bool {
    let command = command.trim();
    if command.is_empty() {
        return false;
    }
    let path = Path::new(command);
    if path.is_absolute() || path.components().count() > 1 {
        path.is_file()
    } else {
        command_exists_on_path(command)
    }
}

fn file_exists_at_known_location_or_on_path(candidates: &[&str], path_file_name: &str) -> bool {
    candidates
        .iter()
        .any(|candidate| Path::new(candidate).is_file())
        || command_exists_on_path(path_file_name)
}

/// Matches the oracle's `IsSafeOpaqueReference`, used across several
/// PodCore/mesh subsystems (quarantine jury, realm subject indexes) to
/// reject identifiers that leak paths, private/local addresses, or raw
/// hashes instead of an opaque reference.
fn is_safe_opaque_reference(value: &str) -> bool {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed.len() > 200 {
        return false;
    }
    let lowered = trimmed.to_ascii_lowercase();
    let has_unsafe_substring = [
        "/",
        "\\",
        "localhost",
        "127.0.0.1",
        "192.168.",
        "10.",
        "172.16.",
        "path",
        "file",
        "private",
        "internal",
    ]
    .iter()
    .any(|needle| lowered.contains(needle));
    if has_unsafe_substring {
        return false;
    }
    !(trimmed.len() >= 32 && trimmed.bytes().all(|byte| byte.is_ascii_hexdigit()))
}

/// Matches the oracle's real `MusicBrainzOverlayService.IsExportableEdit`.
const MUSICBRAINZ_EXPORTABLE_EDIT_TYPES: [&str; 7] = [
    "TitleCorrection",
    "ArtistCorrection",
    "Alias",
    "MissingAltTitle",
    "DuplicateMarker",
    "ReleaseGrouping",
    "RecordingLinkage",
];

fn musicbrainz_edit_is_exportable(edit: &serde_json::Value) -> bool {
    edit.get("type")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|value| MUSICBRAINZ_EXPORTABLE_EDIT_TYPES.contains(&value))
}

fn musicbrainz_edit_upstream_target(edit: &serde_json::Value) -> String {
    format!(
        "{}:{}",
        edit.get("targetType")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default(),
        edit.get("targetId")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default(),
    )
}

fn musicbrainz_edit_proposed_change(edit: &serde_json::Value) -> String {
    format!(
        "{} => {}",
        edit.get("field")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .trim(),
        edit.get("value")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .trim(),
    )
}

/// Matches the oracle's real `MusicBrainzOverlayService.BuildExportReview`,
/// used both by `GET .../export-review` directly and by
/// `POST .../approve-export` to decide `CanApproveExport`/`ReviewReason`.
fn musicbrainz_export_review_json(
    edit: &serde_json::Value,
    decision: Option<&serde_json::Value>,
) -> serde_json::Value {
    let exportable = musicbrainz_edit_is_exportable(edit);
    let review_reason = if decision.is_some() {
        "Upstream export has already been approved locally."
    } else if exportable {
        "Overlay edit can be reviewed for manual upstream MusicBrainz submission."
    } else {
        "Overlay edit type is not exportable."
    };
    serde_json::json!({
        "edit": edit,
        "upstreamTarget": musicbrainz_edit_upstream_target(edit),
        "proposedChange": musicbrainz_edit_proposed_change(edit),
        "evidence": edit.get("evidence").cloned().unwrap_or_else(|| serde_json::json!([])),
        "canApproveExport": decision.is_none() && exportable,
        "reviewReason": review_reason,
        "decision": decision,
    })
}

/// Matches the oracle's `PodAffinityScorer.CalculateTrustScore`: a base
/// trust of 0.5, +0.3 for an owner or +0.2 for a mod, +0.2 for no ban,
/// capped at 1.0.
fn pod_member_trust_score(role: &str, is_banned: bool) -> f64 {
    let role_bonus = match role {
        "owner" => 0.3,
        "mod" => 0.2,
        _ => 0.0,
    };
    let clean_record_bonus = if is_banned { 0.0 } else { 0.2 };
    (0.5_f64 + role_bonus + clean_record_bonus).min(1.0)
}

/// Matches the oracle's `PodOpinionAggregator.CalculateAffinityScore`.
fn pod_member_affinity_score(
    message_count: usize,
    opinion_count: usize,
    membership_duration_seconds: i64,
    is_active: bool,
) -> f64 {
    let activity_score = ((message_count as f64 + opinion_count as f64 * 2.0) / 100.0).min(1.0);
    let duration_months = membership_duration_seconds as f64 / 86_400.0 / 30.0;
    let duration_bonus = (duration_months / 12.0).min(0.3);
    let activity_bonus = if is_active { 0.2 } else { 0.0 };
    let trust_component = (0.5 + activity_score * 0.5).min(1.0);
    (activity_score + duration_bonus + activity_bonus).min(1.0) * trust_component
}

/// Formats a duration the way .NET's default `TimeSpan.ToString()` does:
/// `d.hh:mm:ss` once it spans a full day, else `hh:mm:ss`.
fn format_timespan_hms(total_seconds: i64) -> String {
    let total_seconds = total_seconds.max(0);
    let days = total_seconds / 86_400;
    let hours = (total_seconds % 86_400) / 3_600;
    let minutes = (total_seconds % 3_600) / 60;
    let seconds = total_seconds % 60;
    if days > 0 {
        format!("{days}.{hours:02}:{minutes:02}:{seconds:02}")
    } else {
        format!("{hours:02}:{minutes:02}:{seconds:02}")
    }
}

/// Formats a whole-millisecond duration using the .NET `TimeSpan` JSON
/// representation. Preserve the fractional component when a target stats
/// service reports a sub-second average; the older h:m:s helper intentionally
/// remains unchanged for endpoints whose contract only exposes seconds.
fn format_timespan_millis(total_millis: u64) -> String {
    let total_seconds = total_millis / 1_000;
    let milliseconds = total_millis % 1_000;
    let base = format_timespan_hms(i64::try_from(total_seconds).unwrap_or(i64::MAX));
    if milliseconds == 0 {
        base
    } else {
        // TimeSpan's constant format uses seven fractional decimal places;
        // millisecond counters contribute the first three and four trailing
        // zeroes.
        format!("{base}.{milliseconds:03}0000")
    }
}

/// Matches the oracle's real `SongIdService.BuildEvidencePackage`/
/// `SongIdRunEvidencePackage` contract: a real reshape of the same
/// stored run fields the other SongID endpoints already read/write
/// (scorecard, identityAssessment, syntheticAssessment, track/album/
/// artist candidates, segments, mixGroups, plans, options, evidence),
/// applying the oracle's real sort-by-score/truncate rules and deriving
/// warnings from the same real conditions (incomplete run, no track
/// candidates, no recognizer hits, no forensic matrix). Fields slskR's
/// synchronous, non-fingerprinting analysis pipeline never populates
/// (artifacts from clips/stems/perturbations/a full-source fingerprint,
/// a forensic matrix) are honestly reported as empty/absent rather than
/// fabricated.
fn songid_evidence_package_json(run: &serde_json::Value) -> serde_json::Value {
    fn sorted_candidates(
        run: &serde_json::Value,
        field: &str,
        take: usize,
    ) -> Vec<serde_json::Value> {
        let mut candidates = run
            .get(field)
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        candidates.sort_by(|left, right| {
            let score = |value: &serde_json::Value, field: &str| {
                value
                    .get(field)
                    .and_then(serde_json::Value::as_f64)
                    .unwrap_or(0.0)
            };
            score(right, "actionScore")
                .partial_cmp(&score(left, "actionScore"))
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| {
                    score(right, "identityScore")
                        .partial_cmp(&score(left, "identityScore"))
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
        });
        candidates.truncate(take);
        candidates
    }
    fn taken(run: &serde_json::Value, field: &str, take: usize) -> Vec<serde_json::Value> {
        let mut values = run
            .get(field)
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        values.truncate(take);
        values
    }

    let status = run
        .get("status")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let track_candidates = sorted_candidates(run, "tracks", 10);
    let scorecard = run
        .get("scorecard")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let forensic_matrix = run
        .get("forensicMatrix")
        .cloned()
        .filter(|value| !value.is_null());
    let artifact_directory = run
        .get("artifactDirectory")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();

    let mut artifacts = Vec::new();
    if !artifact_directory.trim().is_empty() {
        artifacts.push(serde_json::json!({
            "kind": "workspace",
            "label": "SongID artifact directory",
            "path": artifact_directory,
        }));
    }
    for (field, kind) in [
        ("clips", "clip"),
        ("stems", "stem"),
        ("perturbations", "perturbation"),
    ] {
        for item in run
            .get(field)
            .and_then(serde_json::Value::as_array)
            .into_iter()
            .flatten()
        {
            let path = item
                .get("path")
                .or_else(|| item.get("fingerprint"))
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            if path.trim().is_empty() {
                continue;
            }
            let label = item
                .get("label")
                .and_then(serde_json::Value::as_str)
                .filter(|label| !label.trim().is_empty())
                .or_else(|| item.get("clipId").and_then(serde_json::Value::as_str))
                .or_else(|| item.get("artifactId").and_then(serde_json::Value::as_str))
                .or_else(|| {
                    item.get("perturbationId")
                        .and_then(serde_json::Value::as_str)
                })
                .unwrap_or_default();
            artifacts.push(serde_json::json!({
                "kind": kind,
                "label": label,
                "path": path,
                "startSeconds": item.get("startSeconds").cloned().unwrap_or(serde_json::Value::Null),
                "durationSeconds": item.get("durationSeconds").cloned().unwrap_or(serde_json::Value::Null),
            }));
        }
    }
    artifacts.truncate(100);

    let mut warnings = Vec::new();
    if !status.eq_ignore_ascii_case("completed") {
        warnings.push("SongID run is not completed; evidence package may be partial.".to_owned());
    }
    if track_candidates.is_empty() {
        warnings.push("No track candidates were produced.".to_owned());
    }
    let hit_count = |field: &str| {
        scorecard
            .get(field)
            .and_then(serde_json::Value::as_i64)
            .unwrap_or(0)
    };
    if hit_count("acoustIdHitCount") == 0
        && hit_count("songRecHitCount") == 0
        && hit_count("panakoHitCount") == 0
        && hit_count("audfprintHitCount") == 0
    {
        warnings.push("No recognizer hits were recorded.".to_owned());
    }
    if forensic_matrix.is_none() {
        warnings.push("No forensic matrix was generated.".to_owned());
    }

    serde_json::json!({
        "runId": run.get("id").cloned().unwrap_or(serde_json::Value::Null),
        "sourceType": run.get("sourceType").cloned().unwrap_or(serde_json::Value::Null),
        "status": status,
        "query": run.get("query").cloned().unwrap_or(serde_json::Value::Null),
        "createdAt": run.get("createdAt").cloned().unwrap_or(serde_json::Value::Null),
        "completedAt": if status.eq_ignore_ascii_case("completed") {
            run.get("createdAt").cloned().unwrap_or(serde_json::Value::Null)
        } else {
            serde_json::Value::Null
        },
        "summary": run.get("summary").cloned().unwrap_or(serde_json::Value::Null),
        "currentStage": run.get("currentStage").cloned().unwrap_or(serde_json::Value::Null),
        "percentComplete": run.get("percentComplete").cloned().unwrap_or(serde_json::json!(0.0)),
        "scorecard": scorecard,
        "identityAssessment": run.get("identityAssessment").cloned().unwrap_or_else(|| serde_json::json!({})),
        "syntheticAssessment": run.get("syntheticAssessment").cloned().unwrap_or_else(|| serde_json::json!({})),
        "forensicMatrix": forensic_matrix,
        "trackCandidates": track_candidates,
        "albumCandidates": sorted_candidates(run, "albums", 6),
        "artistCandidates": sorted_candidates(run, "artists", 6),
        "segments": taken(run, "segments", 12),
        "mixGroups": taken(run, "mixGroups", 12),
        "plans": taken(run, "plans", 20),
        "acquisitionOptions": taken(run, "options", 20),
        "evidence": taken(run, "evidence", 100),
        "artifacts": artifacts,
        "warnings": warnings,
    })
}

/// Matches the oracle's `SongIdCapabilityReporter`: real external-tool
/// presence checks on `PATH` (and, for panako/audfprint, known install
/// locations), not a hardcoded list. Integration-backed capabilities also
/// reflect the configured live clients and required local tools.
fn songid_capabilities_json(integrations: Option<&IntegrationSettings>) -> serde_json::Value {
    const DOCKER_HINT: &str = "For Docker, run install-optional-media-tools with the matching profile or install the tool in a derived image and keep it on PATH.";
    fn capability(
        id: &str,
        label: &str,
        status: &str,
        available: bool,
        reason: String,
        requirements: &[&str],
    ) -> serde_json::Value {
        serde_json::json!({
            "id": id,
            "label": label,
            "status": status,
            "available": available,
            "reason": reason,
            "requirements": requirements,
        })
    }

    fn missing_tools_reason(missing: &[&str]) -> String {
        format!(
            "{} {DOCKER_HINT}",
            match missing {
                [] => "Required tools were not found on PATH.".to_owned(),
                [one] => format!("{one} was not found on PATH."),
                many => format!("{} were not found on PATH.", many.join(" and ")),
            }
        )
    }

    /// Builds the "available" flag and reason for a capability that
    /// requires every named tool to be present.
    fn tool_reason(tools: &[(&str, bool)]) -> (bool, String) {
        let missing = tools
            .iter()
            .filter(|(_, present)| !present)
            .map(|(name, _)| *name)
            .collect::<Vec<_>>();
        let available = missing.is_empty();
        let reason = if available {
            format!(
                "{} {}",
                tools
                    .iter()
                    .map(|(name, _)| *name)
                    .collect::<Vec<_>>()
                    .join(" and "),
                if tools.len() == 1 {
                    "is available."
                } else {
                    "are available."
                }
            )
        } else {
            missing_tools_reason(&missing)
        };
        (available, reason)
    }

    let yt_dlp = command_exists_on_path("yt-dlp");
    let ffmpeg = integrations
        .map(|settings| configured_command_exists(&settings.chromaprint.ffmpeg_path))
        .unwrap_or_else(|| command_exists_on_path("ffmpeg"));
    let songrec = command_exists_on_path("songrec");
    let whisper = command_exists_on_path("whisper");
    let tesseract = command_exists_on_path("tesseract");
    let demucs = command_exists_on_path("demucs");
    let c2patool = command_exists_on_path("c2patool");
    let panako = file_exists_at_known_location_or_on_path(
        &[
            "/usr/share/java/panako.jar",
            "/usr/local/share/java/panako.jar",
            "/usr/share/panako/panako.jar",
            "/usr/local/share/panako/panako.jar",
        ],
        "panako.jar",
    );
    let audfprint = file_exists_at_known_location_or_on_path(
        &[
            "/usr/share/audfprint/audfprint.py",
            "/usr/local/share/audfprint/audfprint.py",
            "/opt/audfprint/audfprint.py",
        ],
        "audfprint.py",
    );

    let (youtube_metadata_available, youtube_metadata_reason) = tool_reason(&[("yt-dlp", yt_dlp)]);
    let (youtube_audio_available, youtube_audio_reason) =
        tool_reason(&[("yt-dlp", yt_dlp), ("ffmpeg", ffmpeg)]);
    let (songrec_available, songrec_reason) = tool_reason(&[("songrec", songrec)]);
    let (demucs_available, demucs_reason) = tool_reason(&[("demucs", demucs), ("ffmpeg", ffmpeg)]);
    let (whisper_available, whisper_reason) =
        tool_reason(&[("whisper", whisper), ("ffmpeg", ffmpeg)]);
    let (ocr_available, ocr_reason) = tool_reason(&[("tesseract", tesseract), ("ffmpeg", ffmpeg)]);
    let (c2pa_available, c2pa_reason) = tool_reason(&[("c2patool", c2patool)]);
    let musicbrainz = integrations.map(|settings| &settings.musicbrainz);
    let musicbrainz_configured =
        musicbrainz.is_some_and(|settings| reqwest::Url::parse(&settings.base_url).is_ok());
    let musicbrainz_reason = if musicbrainz_configured {
        "MusicBrainz client is configured.".to_owned()
    } else {
        "MusicBrainz base URL is not valid.".to_owned()
    };
    let chromaprint_enabled = integrations.is_some_and(|settings| settings.chromaprint.enabled);
    let chromaprint_ffmpeg = integrations
        .is_some_and(|settings| configured_command_exists(&settings.chromaprint.ffmpeg_path));
    let fpcalc = command_exists_on_path("fpcalc");
    let chromaprint_available = chromaprint_enabled && chromaprint_ffmpeg && fpcalc;
    let chromaprint_reason = if !chromaprint_enabled {
        "Chromaprint is disabled; set integration.chromaprint.enabled to enable it.".to_owned()
    } else if !chromaprint_ffmpeg {
        "Configured Chromaprint ffmpeg executable was not found.".to_owned()
    } else if !fpcalc {
        format!("fpcalc/libchromaprint was not found on PATH. {DOCKER_HINT}")
    } else {
        "Chromaprint is enabled and ffmpeg/libchromaprint are available.".to_owned()
    };
    let acoustid_configured = integrations
        .is_some_and(|settings| settings.acoustid.enabled && settings.acoustid.client_id.is_some());
    let acoustid_reason = if acoustid_configured {
        "AcoustID is enabled with a client id.".to_owned()
    } else {
        "Requires integration.acoustid.enabled and a client id.".to_owned()
    };

    serde_json::json!([
        capability(
            "text_query",
            "Text query analysis",
            "stable",
            true,
            "Text searches do not require external tools.".to_owned(),
            &[]
        ),
        capability(
            "url_parsing",
            "YouTube and Spotify URL parsing",
            "experimental",
            true,
            "URL classification and metadata fallback are implemented.".to_owned(),
            &[]
        ),
        capability(
            "musicbrainz_lookup",
            "MusicBrainz lookup",
            "experimental",
            musicbrainz_configured,
            musicbrainz_reason,
            &["musicbrainz base URL"]
        ),
        capability(
            "spotify_page_metadata",
            "Spotify page metadata",
            "experimental",
            true,
            "Spotify page metadata fetch is implemented for public pages.".to_owned(),
            &[]
        ),
        capability(
            "youtube_metadata",
            "YouTube metadata",
            "experimental",
            youtube_metadata_available,
            youtube_metadata_reason.clone(),
            &["yt-dlp"]
        ),
        capability(
            "youtube_audio",
            "YouTube audio extraction",
            "experimental",
            youtube_audio_available,
            youtube_audio_reason,
            &["yt-dlp", "ffmpeg"]
        ),
        capability(
            "local_file_intake",
            "Local file intake",
            "experimental",
            true,
            "Local files are accepted when they are under configured safe directories.".to_owned(),
            &[]
        ),
        capability(
            "chromaprint_fingerprint",
            "Chromaprint fingerprinting",
            "experimental",
            chromaprint_available,
            chromaprint_reason,
            &[
                "integration.chromaprint.enabled",
                "ffmpeg",
                "libchromaprint",
            ],
        ),
        capability(
            "acoustid_lookup",
            "AcoustID lookup",
            "experimental",
            acoustid_configured,
            acoustid_reason,
            &[
                "integration.acoustid.enabled",
                "integration.acoustid.client_id",
            ],
        ),
        capability(
            "songrec",
            "SongRec recognition",
            "experimental",
            songrec_available,
            songrec_reason,
            &["songrec"]
        ),
        capability(
            "panako",
            "Panako local corpus matching",
            "experimental",
            panako,
            if panako {
                "Panako jar found.".to_owned()
            } else {
                format!("panako.jar was not found in known locations or PATH. {DOCKER_HINT}")
            },
            &["java", "panako.jar"],
        ),
        capability(
            "audfprint",
            "Audfprint local corpus matching",
            "experimental",
            audfprint,
            if audfprint {
                "Audfprint script found.".to_owned()
            } else {
                format!("audfprint.py was not found in known locations or PATH. {DOCKER_HINT}")
            },
            &["python", "audfprint.py"],
        ),
        capability(
            "demucs",
            "Demucs stem extraction",
            "experimental",
            demucs_available,
            demucs_reason,
            &["demucs", "ffmpeg"]
        ),
        capability(
            "whisper_transcripts",
            "Whisper transcript extraction",
            "experimental",
            whisper_available,
            whisper_reason,
            &["whisper", "ffmpeg"]
        ),
        capability(
            "ocr_frames",
            "OCR frame scanning",
            "experimental",
            ocr_available,
            ocr_reason,
            &["tesseract", "ffmpeg"]
        ),
        capability(
            "comments_and_chapters",
            "YouTube comments and chapters",
            "experimental",
            youtube_metadata_available,
            youtube_metadata_reason.clone(),
            &["yt-dlp"]
        ),
        capability(
            "c2pa_provenance",
            "C2PA provenance signal detection",
            "experimental",
            c2pa_available,
            c2pa_reason,
            &["c2patool"]
        ),
        capability(
            "hash_from_audio_file_flag",
            "HashFromAudioFileEnabled flag",
            "broken",
            false,
            "Startup validation rejects this flag because PCM extraction support for that hardening path is unavailable.".to_owned(),
            &[]
        ),
    ])
}

fn resolve_external_visualizer_working_directory(
    configured: Option<&Path>,
    resolved_path: Option<&Path>,
) -> Option<PathBuf> {
    if let Some(configured) = configured {
        return configured
            .is_dir()
            .then(|| fs::canonicalize(configured).unwrap_or_else(|_| configured.to_path_buf()));
    }
    resolved_path.and_then(Path::parent).map(Path::to_path_buf)
}

