/// Durable, expiry-bounded JWT revocation storage, matching the oracle's
/// `JwtRevocationStore`: revocations must survive a restart, or a stable
/// configured JWT key (see `SLSKR_JWT_KEY`) would let a previously-revoked
/// token be honored again for the remainder of its lifetime.
#[derive(Debug, Default)]
struct RevokedJwtStore {
    records: BTreeMap<String, u64>,
    state_path: Option<PathBuf>,
}

impl RevokedJwtStore {
    const STATE_FILE_NAME: &'static str = "jwt-revocations.json";
    const MAX_STATE_BYTES: u64 = 8 * 1024 * 1024;
    const MAX_RECORDS: usize = 100_000;
    const MAX_JTI_BYTES: usize = 512;

    fn load(state_dir: &Path) -> Result<Self, String> {
        let state_path = state_dir.join(Self::STATE_FILE_NAME);
        let records = match fs::symlink_metadata(&state_path) {
            Ok(metadata) => {
                if metadata.file_type().is_symlink() || !metadata.is_file() {
                    return Err("JWT revocation state path must be a regular file".to_owned());
                }
                if metadata.len() > Self::MAX_STATE_BYTES {
                    return Err("JWT revocation state file is too large".to_owned());
                }
                let bytes = fs::read(&state_path)
                    .map_err(|error| format!("JWT revocation state read failed: {error}"))?;
                serde_json::from_slice::<BTreeMap<String, u64>>(&bytes)
                    .map_err(|error| format!("JWT revocation state parse failed: {error}"))?
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => BTreeMap::new(),
            Err(error) => {
                return Err(format!("JWT revocation state metadata failed: {error}"));
            }
        };
        if records.len() > Self::MAX_RECORDS
            || records.keys().any(|jti| {
                jti.is_empty()
                    || jti.len() > Self::MAX_JTI_BYTES
                    || jti.chars().any(char::is_control)
            })
        {
            return Err("JWT revocation state exceeds its record or identifier limits".to_owned());
        }
        let mut store = Self {
            records,
            state_path: Some(state_path),
        };
        store.prune(unix_timestamp());
        Ok(store)
    }

    fn revoke(&mut self, jti: String, expires_at: u64, now: u64) -> Result<(), String> {
        self.records.retain(|_, expiry| *expiry > now);
        if expires_at > now {
            self.records.insert(jti, expires_at);
        }
        self.persist()
    }

    fn contains(&mut self, jti: &str, now: u64) -> bool {
        self.prune(now);
        self.records.contains_key(jti)
    }

    fn prune(&mut self, now: u64) {
        let had_expired = self.records.values().any(|expiry| *expiry <= now);
        self.records.retain(|_, expiry| *expiry > now);
        if had_expired {
            if let Err(error) = self.persist() {
                // Keeping an expired revocation on disk is fail-closed; report
                // the failure so operators can repair the state directory.
                eprintln!("[Error] JWT revocation pruning persistence failed: {error}");
            }
        }
    }

    fn persist(&self) -> Result<(), String> {
        let Some(path) = self.state_path.as_deref() else {
            return Ok(());
        };
        let body = serde_json::to_vec(&self.records)
            .map_err(|error| format!("JWT revocation state serialization failed: {error}"))?;
        write_file_atomic(path, body)
            .map_err(|error| format!("JWT revocation state write failed: {error}"))
    }
}

#[derive(Clone, Copy, Debug)]
struct LoginAttempt {
    failures: u8,
    last_failure: u64,
    lockout_until: u64,
}

#[derive(Debug, Default)]
struct LoginAttemptStore {
    records: BTreeMap<String, LoginAttempt>,
}

impl LoginAttemptStore {
    const MAX_RECORDS: usize = 10_000;
    const MAX_FAILURES: u8 = 5;
    const WINDOW_SECONDS: u64 = 10 * 60;
    const LOCKOUT_SECONDS: u64 = 5 * 60;

    fn is_locked(&mut self, keys: &[String], now: u64) -> bool {
        self.prune(now);
        keys.iter().any(|key| {
            self.records
                .get(key)
                .is_some_and(|attempt| attempt.lockout_until > now)
        })
    }

    fn record_failure(&mut self, keys: &[String], now: u64) {
        self.prune(now);
        for key in keys {
            if !self.records.contains_key(key) && self.records.len() >= Self::MAX_RECORDS {
                if let Some(oldest) = self
                    .records
                    .iter()
                    .min_by_key(|(_, attempt)| attempt.last_failure)
                    .map(|(key, _)| key.clone())
                {
                    self.records.remove(&oldest);
                }
            }
            let previous = self.records.get(key).copied();
            let failures = previous
                .filter(|attempt| now.saturating_sub(attempt.last_failure) <= Self::WINDOW_SECONDS)
                .map(|attempt| attempt.failures.saturating_add(1))
                .unwrap_or(1);
            self.records.insert(
                key.clone(),
                LoginAttempt {
                    failures,
                    last_failure: now,
                    lockout_until: if failures >= Self::MAX_FAILURES {
                        now.saturating_add(Self::LOCKOUT_SECONDS)
                    } else {
                        0
                    },
                },
            );
        }
    }

    fn clear(&mut self, keys: &[String]) {
        for key in keys {
            self.records.remove(key);
        }
    }

    fn prune(&mut self, now: u64) {
        self.records.retain(|_, attempt| {
            attempt.lockout_until > now
                || now.saturating_sub(attempt.last_failure) <= Self::WINDOW_SECONDS
        });
    }
}

async fn request_uses_revoked_jwt(state: &AppState, authorization: Option<&str>) -> bool {
    let Some(token) = authorization.and_then(|value| value.strip_prefix("Bearer ")) else {
        return false;
    };
    let now = unix_timestamp();
    let Some(claims) = utils::verify_admin_jwt(&state.config, token, now) else {
        return false;
    };
    state.revoked_jwts.write().await.contains(&claims.jti, now)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LifecycleCommand {
    Shutdown,
    Restart,
}

const GRACEFUL_SHUTDOWN_DISCONNECT_TIMEOUT: Duration = Duration::from_secs(2);

fn schedule_lifecycle_command(state: &AppState, command: LifecycleCommand) {
    let Some(sender) = state.lifecycle_commands.clone() else {
        return;
    };
    tokio::spawn(async move {
        // Let the HTTP response flush before the accept loop tears down the runtime.
        time::sleep(Duration::from_millis(100)).await;
        let _ = sender.send(command).await;
    });
}

/// Disconnects from the Soulseek server (best-effort) before scheduling
/// process shutdown, matching the oracle's `StopAsync` teardown
/// (`Client.Disconnect("Shutting down", ...)`) rather than exiting with the
/// session left connected.
async fn initiate_graceful_shutdown(state: &AppState) {
    // A full session command queue must not prevent the process from honoring
    // SIGTERM/SIGINT. The lifecycle command still closes the listeners after
    // the bounded best-effort disconnect window.
    let _ = time::timeout(
        GRACEFUL_SHUTDOWN_DISCONNECT_TIMEOUT,
        send_session_command(state, SessionCommand::Disconnect),
    )
    .await;
    schedule_lifecycle_command(state, LifecycleCommand::Shutdown);
}

/// Registers a background task that waits for a shutdown signal (SIGTERM,
/// SIGINT, and SIGQUIT on Unix; Ctrl-C on other platforms) and runs the same
/// graceful shutdown sequence as `DELETE /api/application`, matching the
/// oracle's `PosixSignalRegistration`-based teardown -- without this, a
/// `docker stop` or `systemctl stop` hard-kills the process with no drain
/// or clean disconnect at all.
fn spawn_signal_shutdown_handler(state: Arc<AppState>) {
    tokio::spawn(async move {
        wait_for_shutdown_signal().await;
        record_daemon_log(
            &state,
            logging::LogLevel::Info,
            "lifecycle",
            "shutdown signal received; disconnecting and stopping".to_owned(),
        )
        .await;
        initiate_graceful_shutdown(&state).await;
    });
}

#[cfg(unix)]
async fn wait_for_shutdown_signal() {
    use tokio::signal::unix::{signal, SignalKind};
    async fn wait_or_pending(kind: SignalKind) {
        match signal(kind) {
            Ok(mut stream) => {
                stream.recv().await;
            }
            Err(_) => std::future::pending().await,
        }
    }
    tokio::select! {
        () = wait_or_pending(SignalKind::terminate()) => {}
        () = wait_or_pending(SignalKind::interrupt()) => {}
        () = wait_or_pending(SignalKind::quit()) => {}
    }
}

#[cfg(not(unix))]
async fn wait_for_shutdown_signal() {
    let _ = tokio::signal::ctrl_c().await;
}

fn spawn_replacement_process() -> Result<(), String> {
    let executable = std::env::current_exe()
        .map_err(|error| format!("failed to resolve current executable: {error}"))?;
    std::process::Command::new(executable)
        .args(std::env::args_os().skip(1))
        .spawn()
        .map(|_| ())
        .map_err(|error| format!("failed to restart slskr: {error}"))
}

